// Source of truth for run events + WebSocket messages. web/src/shared/protocol.ts must stay identical.

export type ModelId = string; // 'opus' | 'sonnet' | 'haiku' | full id
export type Mode = 'auto' | 'edit' | 'plan' | 'ask';
export type ThinkingLevel = 'off' | 'normal' | 'max';
export type RunStatus = 'queued' | 'running' | 'done' | 'error' | 'aborted';
export type ProjectRole = 'owner' | 'editor' | 'viewer';

export interface Usage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
}

export type RunEvent =
  | { type: 'init'; data: { sessionId: string; model: string; tools: string[]; cwd: string } }
  | { type: 'thinking'; data: { delta: string } }
  | { type: 'text'; data: { delta: string } }
  | { type: 'block_end'; data: { kind: 'thinking' | 'text' } }
  | { type: 'tool_use'; data: { id: string; name: string; input: unknown } }
  | { type: 'tool_result'; data: { id: string; isError: boolean; content: string } }
  | { type: 'todo'; data: { todos: { content: string; status: 'pending' | 'in_progress' | 'completed' }[] } }
  | { type: 'usage'; data: Usage }
  | { type: 'rate_limit'; data: Record<string, unknown> }
  | {
      type: 'result';
      data: {
        sessionId: string;
        isError: boolean;
        result: string;
        durationMs: number;
        numTurns: number;
        costUsd: number;
        usage: Usage;
      };
    }
  | { type: 'error'; data: { message: string } }
  | { type: 'done'; data: { exitCode: number | null } };

export type RunEventType = RunEvent['type'];

export interface Suggestion {
  label: string;
  prompt: string;
  kind: 'next' | 'fix' | 'test' | 'deploy' | 'explain';
}

export type FileChangeKind = 'add' | 'change' | 'unlink' | 'addDir' | 'unlinkDir';

export type ClientMsg =
  | { t: 'sub'; runId: string; fromSeq?: number }
  | { t: 'unsub'; runId: string }
  | { t: 'sub_project'; projectId: string }
  | { t: 'unsub_project'; projectId: string }
  | { t: 'ping' };

export type ServerMsg =
  | ({ t: 'run_event'; runId: string; seq: number } & RunEvent)
  | { t: 'run_status'; runId: string; conversationId: string; projectId: string; status: RunStatus }
  | { t: 'file_change'; projectId: string; path: string; kind: FileChangeKind }
  | { t: 'preview_status'; projectId: string; running: boolean; port: number | null }
  | { t: 'graph_pulse'; projectId: string; intensity: number }
  | { t: 'suggestions'; runId: string; items: Suggestion[] }
  | { t: 'pong' }
  | { t: 'error'; message: string };

// Thin fetch wrapper for /api. All requests are same-origin; cookies carry the session.
export class ApiError extends Error {
  constructor(public status: number, public code: string, message: string) {
    super(message);
  }
}

async function request<T>(method: string, path: string, body?: unknown, init: RequestInit = {}): Promise<T> {
  const isForm = typeof FormData !== 'undefined' && body instanceof FormData;
  const res = await fetch(`/api${path}`, {
    method,
    credentials: 'same-origin',
    headers: {
      'X-Requested-With': 'nxeon',
      ...(body !== undefined && !isForm ? { 'Content-Type': 'application/json' } : {}),
      ...(init.headers || {}),
    },
    body: body === undefined ? undefined : isForm ? (body as FormData) : JSON.stringify(body),
    ...init,
  });
  if (res.status === 204) return undefined as T;
  const ct = res.headers.get('content-type') || '';
  const data = ct.includes('application/json') ? await res.json() : await res.text();
  if (!res.ok) {
    const err = (data as any)?.error;
    if (res.status === 401 && !path.startsWith('/auth/')) window.dispatchEvent(new Event('nx:unauthorized'));
    throw new ApiError(res.status, err?.code || 'http_error', err?.message || res.statusText);
  }
  return data as T;
}

export const api = {
  get: <T>(p: string) => request<T>('GET', p),
  post: <T>(p: string, b?: unknown) => request<T>('POST', p, b ?? {}),
  put: <T>(p: string, b?: unknown) => request<T>('PUT', p, b ?? {}),
  patch: <T>(p: string, b?: unknown) => request<T>('PATCH', p, b ?? {}),
  del: <T>(p: string) => request<T>('DELETE', p),
  /** multipart upload with progress */
  upload<T>(p: string, form: FormData, onProgress?: (frac: number) => void): Promise<T> {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('POST', `/api${p}`);
      xhr.withCredentials = true;
      xhr.setRequestHeader('X-Requested-With', 'nxeon');
      xhr.upload.onprogress = (e) => e.lengthComputable && onProgress?.(e.loaded / e.total);
      xhr.onload = () => {
        let data: any = xhr.responseText;
        try { data = JSON.parse(xhr.responseText); } catch {}
        if (xhr.status >= 200 && xhr.status < 300) resolve(data as T);
        else reject(new ApiError(xhr.status, data?.error?.code || 'upload_failed', data?.error?.message || 'Upload failed'));
      };
      xhr.onerror = () => reject(new ApiError(0, 'network', 'Network error'));
      xhr.send(form);
    });
  },
};
// Singleton auto-reconnecting WebSocket to /ws. Subscriptions are re-sent on reconnect.
import type { ClientMsg, ServerMsg } from '@/shared/protocol';

type Listener = (msg: ServerMsg) => void;

class LiveSocket {
  private ws: WebSocket | null = null;
  private listeners = new Set<Listener>();
  private runSubs = new Map<string, number>(); // runId -> last seq seen
  private projectSubs = new Map<string, number>(); // projectId -> refcount
  private retry = 0;
  private pingTimer: number | undefined;
  connected = false;
  private statusListeners = new Set<(c: boolean) => void>();

  connect() {
    if (this.ws && this.ws.readyState <= 1) return;
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    const ws = new WebSocket(`${proto}://${location.host}/ws`);
    this.ws = ws;
    ws.onopen = () => {
      this.retry = 0;
      this.setConnected(true);
      for (const [runId, seq] of this.runSubs) this.raw({ t: 'sub', runId, fromSeq: seq + 1 });
      for (const projectId of this.projectSubs.keys()) this.raw({ t: 'sub_project', projectId });
      this.pingTimer = window.setInterval(() => this.raw({ t: 'ping' }), 25000);
    };
    ws.onmessage = (e) => {
      let msg: ServerMsg;
      try { msg = JSON.parse(e.data); } catch { return; }
      if (msg.t === 'run_event' && this.runSubs.has(msg.runId)) {
        const last = this.runSubs.get(msg.runId)!;
        if (msg.seq <= last) return; // dedupe replays
        this.runSubs.set(msg.runId, msg.seq);
      }
      this.listeners.forEach((l) => l(msg));
    };
    ws.onclose = () => {
      window.clearInterval(this.pingTimer);
      this.setConnected(false);
      const delay = Math.min(10000, 500 * 2 ** this.retry++);
      window.setTimeout(() => this.connect(), delay);
    };
  }

  private setConnected(c: boolean) {
    this.connected = c;
    this.statusListeners.forEach((l) => l(c));
  }

  private raw(m: ClientMsg) {
    if (this.ws?.readyState === WebSocket.OPEN) this.ws.send(JSON.stringify(m));
  }

  on(l: Listener) { this.listeners.add(l); return () => { this.listeners.delete(l); }; }
  onStatus(l: (c: boolean) => void) { this.statusListeners.add(l); return () => { this.statusListeners.delete(l); }; }

  /** Subscribe to a run's event stream; replays from fromSeq (default 0 = everything). */
  subRun(runId: string, fromSeq = 0) {
    if (!this.runSubs.has(runId)) this.runSubs.set(runId, fromSeq - 1);
    this.raw({ t: 'sub', runId, fromSeq });
  }
  unsubRun(runId: string) { this.runSubs.delete(runId); this.raw({ t: 'unsub', runId }); }

  subProject(projectId: string) {
    const n = this.projectSubs.get(projectId) || 0;
    this.projectSubs.set(projectId, n + 1);
    if (n === 0) this.raw({ t: 'sub_project', projectId });
    return () => {
      const m = (this.projectSubs.get(projectId) || 1) - 1;
      if (m <= 0) { this.projectSubs.delete(projectId); this.raw({ t: 'unsub_project', projectId }); }
      else this.projectSubs.set(projectId, m);
    };
  }
}

export const live = new LiveSocket();
// REST DTOs (mirror server responses). Keep in sync with server/src/routes.
import type { Mode, ModelId, ProjectRole, RunStatus, Suggestion, ThinkingLevel, Usage } from '@/shared/protocol';

export interface User {
  id: string; email: string; name: string; role: 'admin' | 'member'; disabled?: boolean;
  limits?: { dailyTokens?: number | null; models?: string[] | null; modes?: Mode[] | null };
  createdAt?: string; lastSeenAt?: string | null;
}
export interface Project {
  id: string; slug: string; name: string; description: string; color: string; icon: string;
  previewPort: number; previewCommand?: string | null; previewStrip?: boolean; links?: string[];
  archived?: boolean; createdAt: string; lastActiveAt?: string | null; myRole: ProjectRole | 'admin';
}
export interface GraphNode {
  id: string; slug?: string; name: string; color: string; icon?: string;
  status: 'idle' | 'running' | 'error'; activity: number; lastActiveAt?: string | null;
}
export interface Graph { nodes: GraphNode[]; links: { source: string; target: string; kind: string }[] }
export interface Conversation {
  id: string; projectId: string; title: string; claudeSessionId?: string | null;
  model: ModelId; mode: Mode; createdAt: string; updatedAt: string;
}
export interface Attachment { id: string; filename: string; mime: string; size: number; url: string; thumbUrl?: string }
export interface Run {
  id: string; status: RunStatus; model: string; mode: Mode; startedAt: string; endedAt?: string | null;
  inputTokens: number; outputTokens: number; cacheRead: number; cacheWrite: number; costUsd: number; durationMs?: number | null;
}
export interface StoredEvent { seq: number; type: string; data: any }
export interface Message {
  id: string; conversationId: string; role: 'user' | 'assistant'; content: string; attachments: Attachment[];
  runId?: string | null; createdAt: string; userName?: string;
  run?: Run | null; events?: StoredEvent[]; suggestions?: Suggestion[];
}
export interface PromptRequest { text: string; attachments: string[]; model: ModelId; mode: Mode; thinking: ThinkingLevel }
export interface ModelInfo { id: string; label: string }
export interface UsageSummary {
  today: Usage & { runs: number; costUsd: number }; d7: Usage & { runs: number; costUsd: number };
  d30: Usage & { runs: number; costUsd: number }; byModel: { model: string; tokens: number; runs: number }[];
  limits: { dailyTokens: number | null };
}
export interface FileNode { name: string; path: string; type: 'file' | 'dir'; size?: number; children?: FileNode[] }
export interface PreviewStatus { running: boolean; port: number | null; pid?: number | null; logTail?: string; url: string }
import { create } from 'zustand';
import { api } from '@/lib/api';
import type { User } from '@/lib/types';

interface AuthState {
  user: User | null;
  loading: boolean;
  refresh: () => Promise<void>;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
}

export const useAuth = create<AuthState>((set) => ({
  user: null,
  loading: true,
  refresh: async () => {
    try { const { user } = await api.get<{ user: User }>('/auth/me'); set({ user, loading: false }); }
    catch { set({ user: null, loading: false }); }
  },
  login: async (email, password) => {
    const { user } = await api.post<{ user: User }>('/auth/login', { email, password });
    set({ user });
  },
  logout: async () => { await api.post('/auth/logout').catch(() => {}); set({ user: null }); },
}));

window.addEventListener('nx:unauthorized', () => useAuth.setState({ user: null }));
import React from 'react';
import ReactDOM from 'react-dom/client';
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><div>nxeon</div></React.StrictMode>);
