/* Nxeon palette (SPEC §6). Hex vars for direct use, -rgb channel vars for alpha compositing. */
:root {
  --bg: #07050a;        --bg-rgb: 7 5 10;
  --panel: #0f0a12;     --panel-rgb: 15 10 18;
  --panel-2: #160e1a;   --panel-2-rgb: 22 14 26;
  --border: #2a1626;    --border-rgb: 42 22 38;
  --text: #f6e9f0;      --text-rgb: 246 233 240;
  --muted: #a68a99;     --muted-rgb: 166 138 153;
  --pink: #ff3e8a;      --pink-rgb: 255 62 138;
  --hot-pink: #ff6fae;  --hot-pink-rgb: 255 111 174;
  --warm: #ff8a5c;      --warm-rgb: 255 138 92;
  --violet: #b14bff;    --violet-rgb: 177 75 255;
  --success: #3dffb5;   --success-rgb: 61 255 181;
  --warn: #ffc857;      --warn-rgb: 255 200 87;
  --danger: #ff4d6d;    --danger-rgb: 255 77 109;

  --radius: 10px;
  --ease-out: cubic-bezier(.2, .8, .2, 1);
  --topbar-h: 48px;
  color-scheme: dark;
}
EOF
