    content: ''; position: absolute; inset: 0; pointer-events: none; z-index: 1;
    background: repeating-linear-gradient(to bottom, rgb(255 255 255 / 0.018) 0 1px, transparent 1px 3px);
    mix-blend-mode: overlay;
  }
  /* Faint blueprint grid background */
  .nx-grid {
    background-image:
      linear-gradient(rgb(var(--border-rgb) / 0.35) 1px, transparent 1px),
      linear-gradient(90deg, rgb(var(--border-rgb) / 0.35) 1px, transparent 1px);
    background-size: 32px 32px;
  }
  .nx-vignette { box-shadow: inset 0 0 160px 40px rgb(0 0 0 / 0.85); }
  .nx-glow { box-shadow: 0 0 0 1px rgb(var(--pink-rgb) / 0.35), 0 0 22px -4px rgb(var(--pink-rgb) / 0.55); }
  .nx-text-glow { text-shadow: 0 0 12px rgb(var(--pink-rgb) / 0.55); }
  .nx-gradient-text {
