// Tiny floating-position helper shared by Tooltip / Popover (fixed positioning, viewport-clamped).
export type Side = 'top' | 'bottom' | 'left' | 'right';
export type Align = 'start' | 'center' | 'end';

export function computePosition(anchor: DOMRect, floating: { width: number; height: number }, side: Side, align: Align, gap = 8) {
  const vw = window.innerWidth, vh = window.innerHeight, pad = 8;
  let s = side;
  // flip if no room
  if (s === 'bottom' && anchor.bottom + gap + floating.height > vh - pad && anchor.top - gap - floating.height > pad) s = 'top';
  else if (s === 'top' && anchor.top - gap - floating.height < pad && anchor.bottom + gap + floating.height < vh - pad) s = 'bottom';
  else if (s === 'right' && anchor.right + gap + floating.width > vw - pad) s = 'left';
  else if (s === 'left' && anchor.left - gap - floating.width < pad) s = 'right';
  let x = 0, y = 0;
  if (s === 'top' || s === 'bottom') {
    y = s === 'bottom' ? anchor.bottom + gap : anchor.top - gap - floating.height;
    x = align === 'start' ? anchor.left : align === 'end' ? anchor.right - floating.width : anchor.left + anchor.width / 2 - floating.width / 2;
  } else {
    x = s === 'right' ? anchor.right + gap : anchor.left - gap - floating.width;
    y = align === 'start' ? anchor.top : align === 'end' ? anchor.bottom - floating.height : anchor.top + anchor.height / 2 - floating.height / 2;
  }
  x = Math.max(pad, Math.min(vw - floating.width - pad, x));
  y = Math.max(pad, Math.min(vh - floating.height - pad, y));
  return { x, y, side: s };
}
