import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react';
import { cn } from './cn';
import { Tooltip, type TooltipProps } from './Tooltip';

/**
 * IconButton — square icon-only button with built-in tooltip.
 *  icon: ReactNode (required), label: string (required; aria-label + tooltip text)
 *  size: 'xs'(24) | 'sm'(28) | 'md'(32) | 'lg'(40)  (default 'md')
 *  variant: 'ghost' | 'secondary' | 'primary' | 'danger'  (default 'ghost')
 *  active: highlighted toggle state, tooltip: false to disable, tooltipSide: Tooltip side
 */
export interface IconButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  icon: ReactNode; label: string; size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'ghost' | 'secondary' | 'primary' | 'danger'; active?: boolean; tooltip?: boolean; tooltipSide?: TooltipProps['side'];
  shortcut?: string;
}
const sizes = { xs: 'h-6 w-6 rounded', sm: 'h-7 w-7 rounded-md', md: 'h-8 w-8 rounded-md', lg: 'h-10 w-10 rounded-lg' };
const variants = {
  ghost: 'text-muted hover:text-ink hover:bg-white/[0.05]',
  secondary: 'text-ink bg-panel2 border border-line hover:border-pink/40',
  primary: 'bg-pink text-[#16040c] hover:bg-hot shadow-glow-sm',
  danger: 'text-bad hover:bg-bad/10',
};

export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
  { icon, label, size = 'md', variant = 'ghost', active, tooltip = true, tooltipSide = 'bottom', shortcut, className, type = 'button', ...rest },
  ref,
) {
  const btn = (
    <button
      ref={ref}
      type={type}
      aria-label={label}
      aria-pressed={active}
      className={cn(
        'inline-flex shrink-0 items-center justify-center transition-colors duration-150 disabled:opacity-40',
        sizes[size], variants[variant], active && 'text-hot bg-pink/10 hover:bg-pink/15 hover:text-hot', className,
      )}
      {...rest}
    >
      {icon}
    </button>
  );
  return tooltip ? <Tooltip content={label} shortcut={shortcut} side={tooltipSide}>{btn}</Tooltip> : btn;
});
