export interface TextareaProps extends TextareaHTMLAttributes<HTMLTextAreaElement> {
  label?: ReactNode; hint?: ReactNode; error?: ReactNode; autosize?: boolean; maxRows?: number; mono?: boolean; wrapperClassName?: string;
}
export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(function Textarea(
  { label, hint, error, autosize, maxRows = 8, mono, className, wrapperClassName, id, value, ...rest }, ref,
) {
  const auto = useId();
  const iid = id || auto;
  const inner = useRef<HTMLTextAreaElement | null>(null);
  useLayoutEffect(() => {
    const el = inner.current;
    if (!autosize || !el) return;
    el.style.height = 'auto';
