import { useId, type ReactNode, type SelectHTMLAttributes } from 'react';
import { ChevronDown } from 'lucide-react';
import { cn } from './cn';
import { Field, inputBase } from './Input';

/**
 * Select — styled native <select> (accessible, mobile friendly).
 *  options: {value, label, disabled?}[]; value: string; onChange: (value) => void
 *  label?, hint?, error?, size 'sm'|'md', icon? (left), placeholder? (adds empty disabled option)
 */
export interface SelectOption { value: string; label: string; disabled?: boolean }
export interface SelectProps extends Omit<SelectHTMLAttributes<HTMLSelectElement>, 'onChange' | 'size' | 'value'> {
  options: SelectOption[]; value: string; onChange: (value: string) => void;
  label?: ReactNode; hint?: ReactNode; error?: ReactNode; size?: 'sm' | 'md'; icon?: ReactNode; placeholder?: string; wrapperClassName?: string;
}
export function Select({ options, value, onChange, label, hint, error, size = 'md', icon, placeholder, className, wrapperClassName, id, ...rest }: SelectProps) {
  const auto = useId();
  const sid = id || auto;
  const control = (
    <div className={cn('relative flex items-center', !label && wrapperClassName)}>
      {icon && <span className="pointer-events-none absolute left-2.5 text-muted flex">{icon}</span>}
      <select
        id={sid} value={value} onChange={(e) => onChange(e.target.value)}
        className={cn(inputBase, 'appearance-none pr-8 cursor-pointer', size === 'sm' ? 'h-7 text-xs pl-2.5' : 'h-9 text-sm pl-3', icon && 'pl-8', className)}
        {...rest}
      >
        {placeholder !== undefined && <option value="" disabled>{placeholder}</option>}
        {options.map((o) => <option key={o.value} value={o.value} disabled={o.disabled} className="bg-panel">{o.label}</option>)}
      </select>
      <ChevronDown size={14} className="pointer-events-none absolute right-2.5 text-muted" />
    </div>
  );
  if (!label && !hint && !error) return control;
  return <Field label={label} hint={hint} error={error} htmlFor={sid} className={wrapperClassName}>{control}</Field>;
}
