import { Kbd } from './Kbd';

/**
 * Tooltip — hover/focus tooltip rendered in a portal.
 *  content: ReactNode (falsy = no tooltip), side: 'top'|'bottom'|'left'|'right' (default 'top'),
 *  delay ms (default 350), shortcut?: string shown as <Kbd>, className for the wrapper span (inline-flex).
 */
export interface TooltipProps { content: ReactNode; children: ReactNode; side?: Side; delay?: number; shortcut?: string; className?: string }

export function Tooltip({ content, children, side = 'top', delay = 350, shortcut, className }: TooltipProps) {
  const anchor = useRef<HTMLSpanElement>(null);
  const tip = useRef<HTMLDivElement>(null);
  const timer = useRef<number>();
  const [open, setOpen] = useState(false);
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);

  const show = () => { window.clearTimeout(timer.current); timer.current = window.setTimeout(() => setOpen(true), delay); };
  const hide = () => { window.clearTimeout(timer.current); setOpen(false); setPos(null); };

  useLayoutEffect(() => {
    if (!open || !anchor.current || !tip.current) return;
    const r = anchor.current.getBoundingClientRect();
    const t = tip.current.getBoundingClientRect();
    setPos(computePosition(r, t, side, 'center', 6));
  }, [open, side, content]);

  if (!content) return <>{children}</>;
  return (
    <span ref={anchor} className={cn('inline-flex', className)} onMouseEnter={show} onMouseLeave={hide} onFocus={show} onBlur={hide} onPointerDown={hide}>
      {children}
      {open && createPortal(
        <div
          ref={tip} role="tooltip"
          style={{ left: pos?.x ?? -9999, top: pos?.y ?? -9999 }}
          className="fixed z-[1000] pointer-events-none max-w-xs rounded-md border border-line bg-[#120b15]/95 px-2 py-1 text-xs text-ink shadow-panel animate-fade-in flex items-center gap-2"
        >
          <span>{content}</span>{shortcut && <Kbd>{shortcut}</Kbd>}
        </div>,
        document.body,
      )}
    </span>
  );
}
