import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { cn } from './cn';
import { computePosition, type Align, type Side } from './position';

/**
 * Popover — click-to-toggle floating panel in a portal. Closes on outside click / Escape.
 *  trigger: ReactNode (wrapped in an inline-flex span which receives the click)
 *  children: ReactNode | ((close: () => void) => ReactNode)
 *  side 'bottom'|'top'|'left'|'right' (default 'bottom'), align 'start'|'center'|'end' (default 'start')
 *  open/onOpenChange for controlled use; className for the panel; matchWidth to match trigger width.
 */
export interface PopoverProps {
  trigger: ReactNode; children: ReactNode | ((close: () => void) => ReactNode);
  side?: Side; align?: Align; open?: boolean; onOpenChange?: (o: boolean) => void; className?: string; matchWidth?: boolean;
  triggerClassName?: string;
}
export function Popover({ trigger, children, side = 'bottom', align = 'start', open: co, onOpenChange, className, matchWidth, triggerClassName }: PopoverProps) {
  const [uo, setUo] = useState(false);
  const open = co ?? uo;
  const setOpen = useCallback((o: boolean) => { if (co === undefined) setUo(o); onOpenChange?.(o); }, [co, onOpenChange]);
  const anchor = useRef<HTMLSpanElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState<{ x: number; y: number; w: number } | null>(null);

  const place = useCallback(() => {
    if (!anchor.current || !panel.current) return;
    const r = anchor.current.getBoundingClientRect();
    const p = panel.current.getBoundingClientRect();
    const c = computePosition(r, { width: matchWidth ? r.width : p.width, height: p.height }, side, align, 6);
    setPos({ x: c.x, y: c.y, w: r.width });
  }, [side, align, matchWidth]);

  useLayoutEffect(() => { if (open) place(); else setPos(null); }, [open, place]);
  useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => {
      const t = e.target as Node;
      if (panel.current?.contains(t) || anchor.current?.contains(t)) return;
      setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.stopPropagation(); setOpen(false); } };
    const ro = new ResizeObserver(place);
    if (panel.current) ro.observe(panel.current);
    window.addEventListener('pointerdown', onDown, true);
    window.addEventListener('keydown', onKey, true);
    window.addEventListener('resize', place);
    return () => { ro.disconnect(); window.removeEventListener('pointerdown', onDown, true); window.removeEventListener('keydown', onKey, true); window.removeEventListener('resize', place); };
  }, [open, place, setOpen]);

  const close = () => setOpen(false);
  return (
    <>
      <span ref={anchor} className={cn('inline-flex', triggerClassName)} onClick={() => setOpen(!open)}>{trigger}</span>
      {open && createPortal(
        <div
          ref={panel}
          style={{ left: pos?.x ?? -9999, top: pos?.y ?? -9999, width: matchWidth && pos ? pos.w : undefined }}
          className={cn('fixed z-[900] nx-glass rounded-xl p-1.5 animate-pop-in min-w-[10rem]', className)}
        >
          {typeof children === 'function' ? children(close) : children}
        </div>,
        document.body,
      )}
    </>
  );
}

/**
 * Menu — list of actions for use inside a Popover.
 *  items: ({label, icon?, onSelect, danger?, disabled?, shortcut?} | 'sep' | {heading})[]; onClose called after select.
 */
export type MenuItem =
  | { label: ReactNode; icon?: ReactNode; onSelect: () => void; danger?: boolean; disabled?: boolean; shortcut?: string }
  | { heading: ReactNode } | 'sep';
export function Menu({ items, onClose }: { items: MenuItem[]; onClose?: () => void }) {
  return (
    <div role="menu" className="flex flex-col py-0.5">
      {items.map((it, i) => {
        if (it === 'sep') return <div key={i} className="my-1 h-px bg-line" />;
        if ('heading' in it) return <div key={i} className="px-2.5 pt-1.5 pb-1 nx-label">{it.heading}</div>;
        return (
          <button
            key={i} role="menuitem" disabled={it.disabled}
            onClick={() => { it.onSelect(); onClose?.(); }}
            className={cn('flex items-center gap-2.5 rounded-md px-2.5 py-1.5 text-sm text-left transition-colors disabled:opacity-40',
              it.danger ? 'text-bad hover:bg-bad/10' : 'text-ink/90 hover:bg-pink/10 hover:text-ink')}
          >
            {it.icon && <span className="text-muted flex">{it.icon}</span>}
            <span className="flex-1">{it.label}</span>
            {it.shortcut && <span className="text-[10px] font-mono text-muted">{it.shortcut}</span>}
          </button>
        );
      })}
    </div>
  );
}
