import { create } from 'zustand';
import { CheckCircle2, AlertTriangle, Info, XCircle, X } from 'lucide-react';
import type { ReactNode } from 'react';
import { cn } from './cn';

/**
 * Toast system. Mount <Toaster/> once (App does). Call from anywhere:
 *   toast('Saved') · toast.success('Done') · toast.error('Failed', {description}) · toast.warn(...) · toast.info(...)
 *   options: { description?, duration? ms (default 3500; 0 = sticky), action?: {label, onClick} }
 *   returns id; toast.dismiss(id)
 */
export type ToastKind = 'info' | 'success' | 'error' | 'warn';
export interface ToastOpts { description?: ReactNode; duration?: number; action?: { label: string; onClick: () => void } }
interface ToastItem extends ToastOpts { id: number; kind: ToastKind; title: ReactNode }

const useToasts = create<{ items: ToastItem[] }>(() => ({ items: [] }));
let seq = 1;

function push(kind: ToastKind, title: ReactNode, opts: ToastOpts = {}) {
  const id = seq++;
  useToasts.setState((s) => ({ items: [...s.items.slice(-4), { id, kind, title, ...opts }] }));
  const d = opts.duration ?? (kind === 'error' ? 6000 : 3500);
  if (d > 0) window.setTimeout(() => dismiss(id), d);
  return id;
}
function dismiss(id: number) { useToasts.setState((s) => ({ items: s.items.filter((t) => t.id !== id) })); }

export const toast = Object.assign((title: ReactNode, o?: ToastOpts) => push('info', title, o), {
  info: (t: ReactNode, o?: ToastOpts) => push('info', t, o),
  success: (t: ReactNode, o?: ToastOpts) => push('success', t, o),
  error: (t: ReactNode, o?: ToastOpts) => push('error', t, o),
  warn: (t: ReactNode, o?: ToastOpts) => push('warn', t, o),
  dismiss,
});

const icons = {
  info: <Info size={16} className="text-hot" />, success: <CheckCircle2 size={16} className="text-ok" />,
  error: <XCircle size={16} className="text-bad" />, warn: <AlertTriangle size={16} className="text-warn" />,
};
const bars = { info: 'bg-pink', success: 'bg-ok', error: 'bg-bad', warn: 'bg-warn' };

export function Toaster() {
  const items = useToasts((s) => s.items);
  return (
    <div aria-live="polite" className="pointer-events-none fixed bottom-4 right-4 z-[1100] flex w-[min(360px,calc(100vw-2rem))] flex-col gap-2">
      {items.map((t) => (
