/**
 * StatusDot — small status light.
 *  status: 'idle' | 'running' | 'error' | 'ok' | 'warn' | 'offline' | 'queued' | 'done' | 'aborted'
 *  size px (default 8), pulse? (defaults true for running/queued), label? (sr-only text + title)
 */
export type DotStatus = 'idle' | 'running' | 'error' | 'ok' | 'warn' | 'offline' | 'queued' | 'done' | 'aborted';
const col: Record<DotStatus, string> = {
  idle: '#a68a99', running: '#ff3e8a', queued: '#ffc857', error: '#ff4d6d', ok: '#3dffb5', done: '#3dffb5',
  warn: '#ffc857', offline: '#4a3343', aborted: '#ff8a5c',
};
export function StatusDot({ status, size = 8, pulse, label, className }: { status: DotStatus; size?: number; pulse?: boolean; label?: string; className?: string }) {
  const c = col[status] || col.idle;
  const p = pulse ?? (status === 'running' || status === 'queued');
  return (
    <span className={cn('relative inline-flex shrink-0', className)} style={{ width: size, height: size }} title={label || status}>
      {p && <span className="absolute inset-0 rounded-full animate-ping opacity-60" style={{ background: c }} />}
      <span className="relative rounded-full" style={{ width: size, height: size, background: c, boxShadow: status === 'idle' || status === 'offline' ? undefined : `0 0 ${size}px ${c}` }} />
      <span className="sr-only">{label || status}</span>
    </span>
  );
}
