/**
 * Avatar — initials disc with a deterministic warm hue from `name` (or explicit `color`).
 *  name: string, size px (default 28), color?, ring? (pink ring), title shows full name.
 */
const hues = ['#ff3e8a', '#ff6fae', '#ff8a5c', '#b14bff', '#ffc857', '#3dffb5', '#ff4d6d'];
export function hashColor(s: string) { let h = 0; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0; return hues[Math.abs(h) % hues.length]; }
export function initials(name: string) {
  const p = name.trim().split(/[\s@._-]+/).filter(Boolean);
  return ((p[0]?.[0] || '?') + (p.length > 1 ? p[1][0] : p[0]?.[1] || '')).toUpperCase();
}
export function Avatar({ name, size = 28, color, ring, className }: { name: string; size?: number; color?: string; ring?: boolean; className?: string }) {
  const c = color || hashColor(name);
  return (
    <span
      title={name}
      className={cn('inline-flex shrink-0 select-none items-center justify-center rounded-full font-semibold', ring && 'ring-1 ring-pink/60 ring-offset-2 ring-offset-bg', className)}
      style={{ width: size, height: size, fontSize: size * 0.38, color: c, background: `${c}1f`, boxShadow: `inset 0 0 0 1px ${c}55` }}
    >
      {initials(name)}
    </span>
  );
}
