import { useEffect } from 'react';
import { Link } from 'react-router-dom';
import { ArrowRight, Gauge } from 'lucide-react';
import { Popover, Spinner, cn } from '@/components/ui';
import { useUsage, totalTokens } from '@/stores/usage';
import { live } from '@/lib/ws';
import { fmtCompact, fmtUsd } from '@/lib/format';

/** Keeps the usage summary fresh: on mount, every 60 s, and when any run finishes. */
export function useUsageAutoRefresh() {
  const refresh = useUsage((s) => s.refresh);
  useEffect(() => {
    refresh();
    const t = window.setInterval(refresh, 60_000);
    const off = live.on((m) => {
      if (m.t === 'run_status' && (m.status === 'done' || m.status === 'error' || m.status === 'aborted')) window.setTimeout(refresh, 800);
    });
    return () => { window.clearInterval(t); off(); };
  }, [refresh]);
}

function meterTone(frac: number) { return frac >= 0.9 ? 'var(--danger)' : frac >= 0.7 ? 'var(--warn)' : 'var(--pink)'; }

/** Compact top-bar usage meter (today tokens / daily limit) with a details popover. Drop into any top bar. */
export function UsageMeter({ className }: { className?: string }) {
  useUsageAutoRefresh();
  const s = useUsage((x) => x.summary);
  const used = totalTokens(s?.today);
  const limit = s?.limits?.dailyTokens ?? null;
  const frac = limit ? Math.min(1, used / limit) : 0;
  return (
    <Popover
      align="end"
      className="w-[300px] p-0"
      trigger={
        <button
          className={cn('flex h-8 items-center gap-2 rounded-lg px-2 text-xs text-muted transition hover:bg-white/[0.04] hover:text-ink', className)}
          aria-label="Usage today"
        >
          <Gauge size={14} className="text-pink/80" />
          <span className="font-mono tabular text-ink/90">{s ? fmtCompact(used) : '—'}</span>
          {limit ? (
            <>
              <span className="hidden md:block h-1.5 w-14 overflow-hidden rounded-full bg-line">
                <span className="block h-full rounded-full transition-all" style={{ width: `${frac * 100}%`, background: meterTone(frac), boxShadow: `0 0 8px ${meterTone(frac)}` }} />
              </span>
              <span className="hidden lg:inline font-mono text-[10.5px] text-muted">/ {fmtCompact(limit)}</span>
            </>
          ) : null}
        </button>
      }
    >
      {(close) => <UsagePopoverBody onNavigate={close} />}
    </Popover>
  );
}

function UsagePopoverBody({ onNavigate }: { onNavigate: () => void }) {
  const { summary: s, loading } = useUsage();
  if (!s) return <div className="flex justify-center p-6 text-muted">{loading ? <Spinner /> : 'Usage unavailable'}</div>;
  const used = totalTokens(s.today);
  const limit = s.limits?.dailyTokens ?? null;
  const frac = limit ? Math.min(1, used / limit) : 0;
  const maxModel = Math.max(1, ...s.byModel.map((m) => m.tokens));
  return (
    <div>
      <div className="px-4 pt-3.5 pb-3">
        <div className="nx-label">Today</div>
        <div className="mt-1 flex items-baseline gap-2">
          <span className="font-mono text-2xl tabular text-ink">{fmtCompact(used, 2)}</span>
          <span className="text-xs text-muted">tokens{limit ? ` of ${fmtCompact(limit)}` : ' · no daily cap'}</span>
        </div>
        {limit && (
          <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-line">
            <div className="h-full rounded-full" style={{ width: `${frac * 100}%`, background: meterTone(frac), boxShadow: `0 0 10px ${meterTone(frac)}` }} />
          </div>
        )}
      </div>
      <div className="grid grid-cols-3 border-y border-line/70 text-center">
        {([['Today', s.today], ['7 days', s.d7], ['30 days', s.d30]] as const).map(([l, u]) => (
          <div key={l} className="px-2 py-2.5 [&:not(:last-child)]:border-r border-line/70">
            <div className="text-[10px] uppercase tracking-wider text-muted">{l}</div>
            <div className="font-mono text-sm tabular">{fmtCompact(totalTokens(u))}</div>
            <div className="font-mono text-[10.5px] text-muted">{fmtUsd(u.costUsd)} · {u.runs}r</div>
          </div>
        ))}
      </div>
      {s.byModel.length > 0 && (
        <div className="px-4 py-3 space-y-2">
          <div className="nx-label">By model · 30d</div>
          {s.byModel.slice(0, 4).map((m) => (
            <div key={m.model} className="text-xs">
              <div className="flex justify-between"><span className="text-ink/90">{m.model}</span><span className="font-mono text-muted">{fmtCompact(m.tokens)}</span></div>
              <div className="mt-1 h-1 rounded-full bg-line"><div className="h-full rounded-full bg-gradient-to-r from-pink to-warm" style={{ width: `${(m.tokens / maxModel) * 100}%` }} /></div>
            </div>
          ))}
        </div>
      )}
      <Link to="/usage" onClick={onNavigate} className="flex items-center justify-between border-t border-line/70 px-4 py-2.5 text-xs text-hot hover:bg-pink/5">
        Full usage report <ArrowRight size={13} />
      </Link>
    </div>
  );
}
