import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { useNavigate } from 'react-router-dom';
import { CornerDownLeft, Gauge, LayoutDashboard, LogOut, Orbit, Plus, Search, ShieldCheck, Users, ScrollText, Activity, Settings, Radio, Network } from 'lucide-react';
import { Kbd, cn } from '@/components/ui';
import { ProjectBadge } from '@/components/ProjectIcon';
import { useUI } from '@/stores/ui';
import { useProjects } from '@/stores/projects';
import { useAuth } from '@/stores/auth';
import { timeAgo } from '@/lib/format';

interface Cmd { id: string; group: string; label: string; hint?: string; icon: ReactNode; keywords?: string; run: () => void }

/** Simple subsequence fuzzy score (higher = better, -1 = no match). */
function score(q: string, text: string) {
  if (!q) return 0;
  const t = text.toLowerCase();
  const idx = t.indexOf(q);
  if (idx >= 0) return 100 - idx;
  let ti = 0, s = 0;
  for (const ch of q) { const f = t.indexOf(ch, ti); if (f < 0) return -1; s += f === ti ? 2 : 1; ti = f + 1; }
  return s;
}

/** ⌘K / Ctrl+K command palette. Mounted once globally (App). Open via useUI.getState().setPalette(true). */
export function CommandPalette() {
  const open = useUI((s) => s.paletteOpen);
  const setOpen = useUI((s) => s.setPalette);
  const { projects, loaded, load } = useProjects();
  const user = useAuth((s) => s.user);
  const logout = useAuth((s) => s.logout);
  const nav = useNavigate();
  const [q, setQ] = useState('');
  const [sel, setSel] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setOpen(!useUI.getState().paletteOpen); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setOpen]);
  useEffect(() => {
    if (!open) return;
    setQ(''); setSel(0);
    if (!loaded) load();
    window.setTimeout(() => inputRef.current?.focus(), 10);
  }, [open]); // eslint-disable-line react-hooks/exhaustive-deps

  const cmds = useMemo<Cmd[]>(() => {
    const go = (p: string) => () => { setOpen(false); nav(p); };
    const list: Cmd[] = [];
    const sorted = [...projects].filter((p) => !p.archived).sort((a, b) => Date.parse(b.lastActiveAt || b.createdAt) - Date.parse(a.lastActiveAt || a.createdAt));
    for (const p of sorted) list.push({
      id: 'p:' + p.id, group: 'Projects', label: p.name, hint: p.lastActiveAt ? timeAgo(p.lastActiveAt) : p.slug,
      icon: <ProjectBadge name={p.icon} color={p.color} size={22} />, keywords: `${p.slug} ${p.description}`, run: go(`/p/${p.slug}`),
    });
    list.push(
      { id: 'a:new', group: 'Actions', label: 'Create new project', icon: <Plus size={15} />, keywords: 'add new', run: () => useUI.getState().setNewProject(true) },
      { id: 'a:nexus', group: 'Navigate', label: 'Nexus', hint: 'home', icon: <Orbit size={15} />, keywords: 'home graph web', run: go('/') },
      { id: 'a:usage', group: 'Navigate', label: 'My usage', icon: <Gauge size={15} />, keywords: 'tokens cost', run: go('/usage') },
    );
    if (user?.role === 'admin') {
      const adm: [string, string, ReactNode][] = [
        ['', 'Admin · Overview', <LayoutDashboard size={15} />], ['live', 'Admin · Live runs', <Radio size={15} />],
        ['prompts', 'Admin · Prompts', <ScrollText size={15} />], ['users', 'Admin · Users', <Users size={15} />],
        ['projects', 'Admin · Projects', <Network size={15} />], ['traffic', 'Admin · Traffic', <Activity size={15} />],
        ['security', 'Admin · Security', <ShieldCheck size={15} />], ['settings', 'Admin · Settings', <Settings size={15} />],
      ];
      for (const [p, l, i] of adm) list.push({ id: 'adm:' + p, group: 'Admin', label: l, icon: i, keywords: 'admin', run: go(`/admin${p ? '/' + p : ''}`) });
    }
    list.push({ id: 'a:logout', group: 'Account', label: 'Sign out', icon: <LogOut size={15} />, keywords: 'logout exit', run: async () => { setOpen(false); await logout(); nav('/login'); } });
    return list;
  }, [projects, user, nav, setOpen, logout]);

  const results = useMemo(() => {
    const qq = q.trim().toLowerCase();
    if (!qq) return cmds.filter((c) => c.group !== 'Projects' || cmds.indexOf(c) < 8);
    return cmds
      .map((c) => ({ c, s: Math.max(score(qq, c.label), score(qq, c.keywords || '') - 5) }))
      .filter((x) => x.s >= 0).sort((a, b) => b.s - a.s).map((x) => x.c);
  }, [q, cmds]);

  useEffect(() => { setSel(0); }, [q]);
  useEffect(() => { listRef.current?.querySelector(`[data-idx="${sel}"]`)?.scrollIntoView({ block: 'nearest' }); }, [sel]);

  if (!open) return null;
  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') { e.preventDefault(); setSel((s) => Math.min(results.length - 1, s + 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setSel((s) => Math.max(0, s - 1)); }
    else if (e.key === 'Enter') { e.preventDefault(); results[sel]?.run(); }
    else if (e.key === 'Escape') { e.preventDefault(); setOpen(false); }
  };
  let lastGroup = '';
  return createPortal(
    <div className="fixed inset-0 z-[950] flex items-start justify-center p-4 pt-[14vh]" onKeyDown={onKey}>
      <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px] animate-fade-in" onClick={() => setOpen(false)} />
      <div role="dialog" aria-label="Command palette" className="relative w-full max-w-[580px] overflow-hidden nx-glass rounded-2xl animate-pop-in">
        <div className="absolute inset-x-10 top-0 h-px bg-gradient-to-r from-transparent via-pink to-transparent" />
        <div className="flex items-center gap-3 border-b border-line px-4">
          <Search size={16} className="text-pink" />
          <input
            ref={inputRef} value={q} onChange={(e) => setQ(e.target.value)}
            placeholder="Jump to a project or run a command…"
            className="h-12 flex-1 bg-transparent text-[15px] placeholder:text-muted/60 focus-visible:outline-none focus-visible:shadow-none"
            aria-activedescendant={results[sel]?.id}
          />
          <Kbd>esc</Kbd>
        </div>
        <div ref={listRef} className="max-h-[50vh] overflow-y-auto p-1.5" role="listbox">
          {results.length === 0 && <div className="px-3 py-8 text-center text-sm text-muted">No matches for “{q}”.</div>}
          {results.map((c, i) => {
            const head = c.group !== lastGroup ? (lastGroup = c.group) : null;
            return (
              <div key={c.id}>
                {head && <div className="px-2.5 pb-1 pt-2.5 nx-label !text-[10px]">{head}</div>}
                <button
                  id={c.id} data-idx={i} role="option" aria-selected={i === sel}
