  useEffect(() => {
    if (skip) return;
    let i = 0; let t: number;
    const step = () => {
      i++; setLines(i);
      if (i < BOOT.length) t = window.setTimeout(step, BOOT[i].delay);
      else t = window.setTimeout(() => { setReady(true); sessionStorage.setItem('nx_booted', '1'); }, 380);
    };
    t = window.setTimeout(step, 250);
    const finish = () => { window.clearTimeout(t); setLines(BOOT.length); setReady(true); };
    window.addEventListener('keydown', finish, { once: true });
    window.addEventListener('pointerdown', finish, { once: true });
    return () => { window.clearTimeout(t); window.removeEventListener('keydown', finish); window.removeEventListener('pointerdown', finish); };
  }, [skip]);
