// Nexus canvas engine — framework-free. Renders the spider-web project network with Canvas 2D.
// World space: core at (0,0). Camera maps world → screen: s = (w - cam) * k + viewport/2.
import {
  forceCollide, forceLink, forceManyBody, forceRadial, forceSimulation,
  type Simulation, type SimulationLinkDatum, type SimulationNodeDatum,
} from 'd3-force';
import type { Graph, GraphNode } from '@/lib/types';

export type NodeKind = 'core' | 'project' | 'ghost';
export type NodeStatus = 'idle' | 'running' | 'error';

export interface SimNode extends SimulationNodeDatum {
  id: string; kind: NodeKind; data?: GraphNode; r: number; ringR: number;
  color: string; rgb: [number, number, number]; status: NodeStatus; activity: number;
  phase: number; flash: number; ripples: number[]; pinned: boolean; label: string;
  x: number; y: number;
}
interface Strand { a: SimNode; b: SimNode; kind: string; phase: number; core: boolean; len: number; cx: number; cy: number }
interface Pulse { s: Strand; t: number; speed: number; dir: 1 | -1; rgb: [number, number, number]; size: number }
interface Star { x: number; y: number; z: number; tw: number; s: number }

export interface EngineCallbacks {
  onHover?: (n: SimNode | null) => void;
  onOpen?: (n: SimNode) => void; // click on a project node
  onGhost?: () => void; // click on "+ New project"
  onCameraIdle?: () => void;
}

const POS_KEY = 'nx.nexus.pos.v1';
const CORE_R = 30;
const MAX_PULSES = 450;
const TAU = Math.PI * 2;

function hexToRgb(h: string): [number, number, number] {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(h?.trim() || '');
  if (!m) return [255, 62, 138];
  let s = m[1];
  if (s.length === 3) s = s.split('').map((c) => c + c).join('');
  const n = parseInt(s, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
const rgba = (c: [number, number, number], a: number) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
const PINK: [number, number, number] = [255, 62, 138];
const HOT: [number, number, number] = [255, 111, 174];
const RED: [number, number, number] = [255, 77, 109];
const WARM: [number, number, number] = [255, 138, 92];

// deterministic rng
function mulberry(seed: number) {
  return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}
function hashStr(s: string) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }

function loadPositions(): Record<string, { x: number; y: number }> {
  try { return JSON.parse(localStorage.getItem(POS_KEY) || '{}') || {}; } catch { return {}; }
}
function savePositions(p: Record<string, { x: number; y: number }>) {
  try { localStorage.setItem(POS_KEY, JSON.stringify(p)); } catch { /* ignore */ }
}

export class NexusEngine {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private cb: EngineCallbacks;
  private dpr = 1; private W = 0; private H = 0;
  private raf = 0; private last = 0; private time = 0;
  private running = false;
  private reduced: boolean;
  private dirty = true;

  nodes: SimNode[] = [];
  private byId = new Map<string, SimNode>();
  private strands: Strand[] = [];
  private nodeStrands = new Map<string, Strand[]>();
  private pulses: Pulse[] = [];
  private stars: Star[] = [];
  private sim: Simulation<SimNode, SimulationLinkDatum<SimNode>>;
  private positions = loadPositions();

  // camera
  cam = { x: 0, y: 0, k: 1 };
  private target = { x: 0, y: 0, k: 1 };
  private tween: { from: { x: number; y: number; k: number }; to: { x: number; y: number; k: number }; t0: number; dur: number; done?: () => void } | null = null;
  private outerR = 300;
  private webPath: Path2D | null = null;
  private spokePath: Path2D | null = null;

  // interaction
  hovered: SimNode | null = null;
  private focusId: string | null = null; // externally highlighted (list hover)
  private pointers = new Map<number, { x: number; y: number }>();
  private drag: { mode: 'pan' | 'node' | 'pinch'; node?: SimNode; sx: number; sy: number; moved: boolean; camX: number; camY: number; dist?: number; k0?: number } | null = null;
  private hoverEl: HTMLElement | null = null;
  private icons = new Map<string, HTMLImageElement>();
  private sprites = new Map<string, HTMLCanvasElement>();
  private ro: ResizeObserver;
  private disposed = false;

  constructor(canvas: HTMLCanvasElement, cb: EngineCallbacks = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false })!;
    this.cb = cb;
    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.sim = forceSimulation<SimNode>([]).stop();
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(canvas);
    this.resize();
    this.makeStars();
    this.bind();
    document.addEventListener('visibilitychange', this.onVis);
    this.start();
  }

  // ---------- public API ----------
  setIcons(map: Map<string, HTMLImageElement>) { this.icons = map; this.dirty = true; }
  setHoverElement(el: HTMLElement | null) { this.hoverEl = el; }
  setFocus(id: string | null) { this.focusId = id; this.dirty = true; }

  setGraph(g: Graph) {
    const prev = this.byId;
    const nodes: SimNode[] = [];
    const core = prev.get('core') || this.mkNode('core', 'core', undefined);
    core.fx = 0; core.fy = 0; core.x = 0; core.y = 0;
    nodes.push(core);

    const projects = g.nodes.filter((n) => n.id !== 'core');
    // most recently active → inner rings
    const sorted = [...projects].sort((a, b) => (Date.parse(b.lastActiveAt || '') || 0) - (Date.parse(a.lastActiveAt || '') || 0));
    let ring = 1, inRing = 0, cap = 6;
    const rings: { n: GraphNode; ring: number; idx: number; cap: number }[] = [];
    for (const n of sorted) {
      rings.push({ n, ring, idx: inRing, cap });
      if (++inRing >= cap) { ring++; inRing = 0; cap = 6 + (ring - 1) * 5; }
    }
    const ringR = (i: number) => 170 + (i - 1) * 120;
    for (const { n, ring: ri, idx, cap: c } of rings) {
      let sn = prev.get(n.id);
      const remaining = Math.min(c, sorted.length - rings.findIndex((x) => x.ring === ri));
      const count = Math.max(1, Math.min(c, remaining));
      if (!sn) {
        sn = this.mkNode(n.id, 'project', n);
        const off = (hashStr('ring' + ri) % 1000) / 1000 * TAU;
        const a = off + (idx / count) * TAU;
        const saved = this.positions[n.id];
        if (saved) { sn.x = saved.x; sn.y = saved.y; sn.fx = saved.x; sn.fy = saved.y; sn.pinned = true; }
        else { sn.x = Math.cos(a) * ringR(ri); sn.y = Math.sin(a) * ringR(ri); }
      }
      sn.data = n; sn.label = n.name; sn.color = n.color || '#ff3e8a'; sn.rgb = hexToRgb(sn.color);
      sn.status = n.status || 'idle'; sn.activity = Math.max(0, Math.min(1, n.activity || 0));
      sn.ringR = ringR(ri);
      sn.r = 15 + sn.activity * 5;
      nodes.push(sn);
    }
    const maxRing = rings.length ? rings[rings.length - 1].ring : 0;
    const ghost = prev.get('__ghost') || this.mkNode('__ghost', 'ghost', undefined);
    ghost.ringR = ringR(maxRing + 1) - (maxRing ? 40 : 30);
    if (!prev.get('__ghost')) {
      const a = -Math.PI * 0.25;
      ghost.x = Math.cos(a) * ghost.ringR; ghost.y = Math.sin(a) * ghost.ringR;
    }
    nodes.push(ghost);

    this.nodes = nodes;
    this.byId = new Map(nodes.map((n) => [n.id, n]));
    this.outerR = ringR(Math.max(1, maxRing)) + 150;

    // strands: core spokes + graph links
    const strands: Strand[] = [];
    const seen = new Set<string>();
    const add = (a: SimNode | undefined, b: SimNode | undefined, kind: string, core: boolean) => {
      if (!a || !b || a === b) return;
      const key = a.id < b.id ? a.id + '|' + b.id : b.id + '|' + a.id;
      if (seen.has(key)) return; seen.add(key);
      strands.push({ a, b, kind, core, phase: (hashStr(key) % 1000) / 1000 * TAU, len: 0, cx: 0, cy: 0 });
    };
    for (const n of nodes) if (n.kind === 'project') add(core, n, 'core', true);
    add(core, ghost, 'ghost', true);
    for (const l of g.links) {
      const s = typeof l.source === 'string' ? l.source : (l.source as any)?.id;
      const t = typeof l.target === 'string' ? l.target : (l.target as any)?.id;
      add(this.byId.get(s), this.byId.get(t), l.kind, s === 'core' || t === 'core');
    }
    this.strands = strands;
    this.nodeStrands = new Map();
    for (const s of strands) {
      for (const n of [s.a, s.b]) { const arr = this.nodeStrands.get(n.id) || []; arr.push(s); this.nodeStrands.set(n.id, arr); }
    }
    this.pulses = this.pulses.filter((p) => strands.includes(p.s));
    this.buildWeb();

    // forces
    const projLinks = strands.filter((s) => !s.core).map((s) => ({ source: s.a, target: s.b }));
    this.sim = forceSimulation<SimNode>(nodes)
      .force('charge', forceManyBody<SimNode>().strength((n) => (n.kind === 'core' ? -400 : -90)).distanceMax(400))
      .force('collide', forceCollide<SimNode>().radius((n) => (n.kind === 'core' ? CORE_R + 50 : n.r + 28)).strength(0.9))
      .force('radial', forceRadial<SimNode>((n) => n.ringR, 0, 0).strength((n) => (n.kind === 'core' ? 0 : 0.35)))
      .force('link', forceLink<SimNode, SimulationLinkDatum<SimNode>>(projLinks).distance(150).strength(0.03))
      .alphaDecay(0.035)
      .stop();
    const fresh = nodes.some((n) => !prev.has(n.id));
    if (fresh) { this.sim.alpha(1); for (let i = 0; i < 220; i++) this.sim.tick(); }
    this.sim.alpha(this.reduced ? 0 : 0.15);
    if (prev.size <= 1 || fresh && prev.size === 0) this.fit(true);
    this.dirty = true;
  }

  /** Update one project's status (from run_status). */
  setStatus(projectId: string, status: NodeStatus) {
    const n = this.byId.get(projectId);
    if (!n || n.kind !== 'project') return;
    if (n.status !== status && status === 'running') n.flash = 1;
    n.status = status; this.dirty = true;
  }

  /** graph_pulse: fire light along all strands of a node. */
  pulse(projectId: string, intensity = 0.5) {
    const n = this.byId.get(projectId);
    if (!n) return;
    n.flash = Math.min(1.5, n.flash + 0.6 + intensity * 0.4);
    n.activity = Math.min(1, n.activity + intensity * 0.05);
    if (this.reduced) { this.dirty = true; return; }
    n.ripples.push(0);
    if (n.ripples.length > 4) n.ripples.shift();
    const strands = this.nodeStrands.get(n.id) || [];
    const count = 1 + Math.round(intensity * 4);
    for (const s of strands) for (let i = 0; i < count; i++) {
      this.spawn(s, s.a === n ? 1 : -1, n.rgb, 1 + intensity, i * -0.08);
    }
  }

  zoomBy(f: number) { this.zoomAt(this.W / 2, this.H / 2, f); }

  fit(instant = false) {
    const pad = 0.9;
    const k = Math.max(0.25, Math.min(1.6, (Math.min(this.W, this.H) / 2 / (this.outerR - 60)) * pad));
    this.animateTo({ x: 0, y: 0, k }, instant ? 0 : 600);
  }

  resetLayout() {
    this.positions = {}; savePositions({});
    for (const n of this.nodes) if (n.kind !== 'core') { n.fx = null; n.fy = null; n.pinned = false; }
    this.sim.alpha(0.9);
    if (this.reduced) for (let i = 0; i < 200; i++) this.sim.tick();
    this.dirty = true;
  }

  /** Camera fly-in to a node, then call done. */
  flyTo(id: string, done: () => void) {
    const n = this.byId.get(id);
    if (!n || this.reduced) { done(); return; }
    this.animateTo({ x: n.x, y: n.y, k: Math.max(3.2, this.cam.k * 3) }, 650, done);
  }

  screenPos(n: SimNode) {
    return { x: (n.x - this.cam.x) * this.cam.k + this.W / 2, y: (n.y - this.cam.y) * this.cam.k + this.H / 2 };
  }

  dispose() {
    this.disposed = true;
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    document.removeEventListener('visibilitychange', this.onVis);
    this.unbind();
    this.sim.stop();
  }

  // ---------- internals ----------
  private mkNode(id: string, kind: NodeKind, data?: GraphNode): SimNode {
    const color = kind === 'core' ? '#ff3e8a' : data?.color || '#ff3e8a';
    return {
      id, kind, data, r: kind === 'core' ? CORE_R : kind === 'ghost' ? 15 : 16, ringR: 0, color, rgb: hexToRgb(color),
      status: data?.status || 'idle', activity: data?.activity || 0, phase: (hashStr(id) % 1000) / 1000 * TAU,
      flash: 0, ripples: [], pinned: false, label: kind === 'ghost' ? 'New project' : data?.name || 'core', x: 0, y: 0,
    };
  }

  private makeStars() {
    const rnd = mulberry(1337);
    this.stars = Array.from({ length: 240 }, () => ({ x: rnd() * 4000, y: rnd() * 4000, z: 0.04 + rnd() * rnd() * 0.35, tw: rnd() * TAU, s: rnd() < 0.08 ? 1.6 : rnd() < 0.4 ? 1.1 : 0.7 }));
  }

  private buildWeb() {
    // Orb-web: radial spokes + sagging capture rings with slight organic jitter.
    const rnd = mulberry(424242);
    const spokes = 28;
    const R = this.outerR;
    const angles = Array.from({ length: spokes }, (_, i) => (i / spokes) * TAU + (rnd() - 0.5) * 0.08);
    const sp = new Path2D();
    for (const a of angles) { sp.moveTo(Math.cos(a) * 46, Math.sin(a) * 46); sp.lineTo(Math.cos(a) * R * 1.35, Math.sin(a) * R * 1.35); }
    this.spokePath = sp;
    const web = new Path2D();
    const gap = 46;
    for (let r = 64; r < R * 1.25; r += gap * (0.88 + rnd() * 0.24)) {
      const pts = angles.map((a) => { const rr = r * (0.97 + rnd() * 0.06); return [Math.cos(a) * rr, Math.sin(a) * rr, rr] as const; });
      web.moveTo(pts[0][0], pts[0][1]);
      for (let i = 0; i < spokes; i++) {
        const p = pts[i], q = pts[(i + 1) % spokes];
        const am = (angles[i] + (i === spokes - 1 ? angles[0] + TAU : angles[(i + 1) % spokes])) / 2;
        const sag = ((p[2] + q[2]) / 2) * 0.955;
        web.quadraticCurveTo(Math.cos(am) * sag, Math.sin(am) * sag, q[0], q[1]);
      }
    }
    this.webPath = web;
  }

  private spawn(s: Strand, dir: 1 | -1, rgb: [number, number, number], size = 1, t0 = 0) {
    if (this.pulses.length >= MAX_PULSES) this.pulses.shift();
    const len = Math.max(60, Math.hypot(s.b.x - s.a.x, s.b.y - s.a.y));
    this.pulses.push({ s, t: t0, dir, rgb, size, speed: (150 + Math.random() * 90) / len * (size > 1 ? 1.4 : 1) });
  }

  private sprite(rgb: [number, number, number]) {
    const key = rgb.join(',');
    let c = this.sprites.get(key);
    if (!c) {
      c = document.createElement('canvas'); c.width = c.height = 64;
      const g = c.getContext('2d')!;
      const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
      gr.addColorStop(0, `rgba(255,240,248,1)`);
      gr.addColorStop(0.12, rgba(rgb, 0.95));
      gr.addColorStop(0.4, rgba(rgb, 0.28));
      gr.addColorStop(1, rgba(rgb, 0));
      g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
      this.sprites.set(key, c);
    }
    return c;
  }
  private haloSprite(rgb: [number, number, number]) {
    const key = 'h' + rgb.join(',');
    let c = this.sprites.get(key);
    if (!c) {
      c = document.createElement('canvas'); c.width = c.height = 128;
      const g = c.getContext('2d')!;
      const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
      gr.addColorStop(0, rgba(rgb, 0.55)); gr.addColorStop(0.35, rgba(rgb, 0.18)); gr.addColorStop(1, rgba(rgb, 0));
      g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
      this.sprites.set(key, c);
    }
    return c;
  }

  private resize() {
    const r = this.canvas.getBoundingClientRect();
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.W = Math.max(1, r.width); this.H = Math.max(1, r.height);
    this.canvas.width = Math.round(this.W * this.dpr);
    this.canvas.height = Math.round(this.H * this.dpr);
    this.dirty = true;
    if (this.reduced && this.running) this.frame(performance.now());
  }

  private onVis = () => { if (document.hidden) this.stop(); else this.start(); };
  private start() {
    if (this.running || this.disposed) return;
    this.running = true; this.last = performance.now();
    this.raf = requestAnimationFrame(this.loop);
  }
  private stop() { this.running = false; cancelAnimationFrame(this.raf); }
  private loop = (now: number) => {
    if (!this.running) return;
    this.frame(now);
    this.raf = requestAnimationFrame(this.loop);
  };

  private animateTo(to: { x: number; y: number; k: number }, dur: number, done?: () => void) {
    if (dur <= 0 || this.reduced) {
      this.cam = { ...to }; this.target = { ...to }; this.tween = null; this.dirty = true; done?.(); return;
    }
    this.tween = { from: { ...this.cam }, to, t0: performance.now(), dur, done };
    this.target = { ...to };
  }

  private zoomAt(sx: number, sy: number, f: number) {
    const k0 = this.target.k;
    const k1 = Math.max(0.2, Math.min(5, k0 * f));
    // keep world point under cursor fixed (relative to target camera)
    const wx = (sx - this.W / 2) / k0 + this.target.x;
    const wy = (sy - this.H / 2) / k0 + this.target.y;
    this.target = { k: k1, x: wx - (sx - this.W / 2) / k1, y: wy - (sy - this.H / 2) / k1 };
    this.tween = null;
    if (this.reduced) this.cam = { ...this.target };
    this.dirty = true;
  }

  private toWorld(sx: number, sy: number) {
    return { x: (sx - this.W / 2) / this.cam.k + this.cam.x, y: (sy - this.H / 2) / this.cam.k + this.cam.y };
  }

  private hit(sx: number, sy: number): SimNode | null {
    const w = this.toWorld(sx, sy);
    let best: SimNode | null = null, bd = Infinity;
    for (const n of this.nodes) {
      const d = Math.hypot(n.x - w.x, n.y - w.y);
      const lim = n.r + 8 / this.cam.k;
      if (d < lim && d < bd) { bd = d; best = n; }
    }
    return best;
  }

  private setHover(n: SimNode | null) {
    if (n === this.hovered) return;
    this.hovered = n;
    this.canvas.style.cursor = n && n.kind !== 'core' ? 'pointer' : this.drag?.mode === 'pan' ? 'grabbing' : 'grab';
    this.cb.onHover?.(n && n.kind === 'project' ? n : null);
    this.dirty = true;
  }

  // ----- events -----
  private bind() {
    const c = this.canvas;
    c.addEventListener('pointerdown', this.onDown);
    window.addEventListener('pointermove', this.onMove);
    window.addEventListener('pointerup', this.onUp);
    window.addEventListener('pointercancel', this.onUp);
    c.addEventListener('wheel', this.onWheel, { passive: false });
    c.addEventListener('dblclick', this.onDbl);
    c.addEventListener('pointerleave', this.onLeave);
    c.style.cursor = 'grab';
    c.style.touchAction = 'none';
  }
  private unbind() {
    const c = this.canvas;
    c.removeEventListener('pointerdown', this.onDown);
    window.removeEventListener('pointermove', this.onMove);
    window.removeEventListener('pointerup', this.onUp);
    window.removeEventListener('pointercancel', this.onUp);
    c.removeEventListener('wheel', this.onWheel);
    c.removeEventListener('dblclick', this.onDbl);
    c.removeEventListener('pointerleave', this.onLeave);
  }
  private local(e: { clientX: number; clientY: number }) {
    const r = this.canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }
  private onDown = (e: PointerEvent) => {
    const p = this.local(e);
    this.pointers.set(e.pointerId, p);
    try { this.canvas.setPointerCapture(e.pointerId); } catch { /* noop */ }
    if (this.pointers.size === 2) {
      const [a, b] = [...this.pointers.values()];
      this.drag = { mode: 'pinch', sx: (a.x + b.x) / 2, sy: (a.y + b.y) / 2, moved: true, camX: this.cam.x, camY: this.cam.y, dist: Math.hypot(a.x - b.x, a.y - b.y), k0: this.target.k };
      return;
    }
    const n = this.hit(p.x, p.y);
    this.tween = null;
    if (n && n.kind !== 'core') this.drag = { mode: 'node', node: n, sx: p.x, sy: p.y, moved: false, camX: 0, camY: 0 };
    else { this.drag = { mode: 'pan', sx: p.x, sy: p.y, moved: false, camX: this.target.x, camY: this.target.y }; this.canvas.style.cursor = 'grabbing'; }
  };
  private onMove = (e: PointerEvent) => {
    const p = this.local(e);
    if (this.pointers.has(e.pointerId)) this.pointers.set(e.pointerId, p);
    const d = this.drag;
    if (!d) {
      if (e.target === this.canvas) this.setHover(this.hit(p.x, p.y));
      return;
    }
    if (d.mode === 'pinch' && this.pointers.size >= 2) {
      const [a, b] = [...this.pointers.values()];
      const dist = Math.hypot(a.x - b.x, a.y - b.y);
      const f = dist / (d.dist || dist);
      const mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
      const k1 = Math.max(0.2, Math.min(5, (d.k0 || 1) * f));
      this.zoomAt(mx, my, k1 / this.target.k);
      this.cam = { ...this.target };
      return;
    }
    const dx = p.x - d.sx, dy = p.y - d.sy;
    if (!d.moved && Math.hypot(dx, dy) > 4) d.moved = true;
    if (!d.moved) return;
    if (d.mode === 'pan') {
      this.target.x = d.camX - dx / this.cam.k; this.target.y = d.camY - dy / this.cam.k;
      this.cam.x = this.target.x; this.cam.y = this.target.y;
      this.dirty = true;
    } else if (d.mode === 'node' && d.node) {
      const w = this.toWorld(p.x, p.y);
      d.node.fx = w.x; d.node.fy = w.y; d.node.x = w.x; d.node.y = w.y;
      if (!this.reduced) this.sim.alphaTarget(0.12).alpha(Math.max(this.sim.alpha(), 0.12));
      this.setHover(d.node);
      this.dirty = true;
    }
  };
  private onUp = (e: PointerEvent) => {
    this.pointers.delete(e.pointerId);
    const d = this.drag;
    if (!d) return;
    if (d.mode === 'pinch') { if (this.pointers.size === 0) this.drag = null; return; }
    this.drag = null;
    this.canvas.style.cursor = this.hovered ? 'pointer' : 'grab';
    if (d.mode === 'node' && d.node) {
      if (d.moved) {
        d.node.pinned = true;
        if (d.node.kind === 'project') { this.positions[d.node.id] = { x: Math.round(d.node.x), y: Math.round(d.node.y) }; savePositions(this.positions); }
        this.sim.alphaTarget(0);
      } else if (d.node.kind === 'ghost') this.cb.onGhost?.();
      else if (d.node.kind === 'project') this.cb.onOpen?.(d.node);
    }
  };
  private onLeave = () => { if (!this.drag) this.setHover(null); };
  private onWheel = (e: WheelEvent) => {
    e.preventDefault();
    const p = this.local(e);
    const delta = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
    this.zoomAt(p.x, p.y, Math.exp(-delta * (e.ctrlKey ? 0.01 : 0.0015)));
  };
  private onDbl = (e: MouseEvent) => {
    const p = this.local(e);
    const n = this.hit(p.x, p.y);
    if (n && n.kind === 'project') return;
    this.fit();
  };

  // ----- frame -----
  private frame(now: number) {
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    const animating = !this.reduced;
    if (animating) this.time += dt;

    // simulation
    if (this.sim.alpha() > this.sim.alphaMin() || (this.sim as any).alphaTarget?.() > 0) {
      this.sim.tick(); this.dirty = true;
    }

    // camera
    if (this.tween) {
      const u = Math.min(1, (now - this.tween.t0) / this.tween.dur);
      const e = u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
      const { from, to } = this.tween;
      // zoom interpolated geometrically
      this.cam.k = from.k * Math.pow(to.k / from.k, e);
      this.cam.x = from.x + (to.x - from.x) * e; this.cam.y = from.y + (to.y - from.y) * e;
      this.dirty = true;
      if (u >= 1) { const d = this.tween.done; this.tween = null; d?.(); }
    } else {
      const f = 1 - Math.exp(-dt * 12);
      const dx = this.target.x - this.cam.x, dy = this.target.y - this.cam.y, dk = this.target.k - this.cam.k;
      if (Math.abs(dx) + Math.abs(dy) > 0.01 || Math.abs(dk) > 0.0005) {
        this.cam.x += dx * f; this.cam.y += dy * f; this.cam.k += dk * f; this.dirty = true;
      }
    }

    if (animating) {
      this.updatePulses(dt);
      for (const n of this.nodes) {
        if (n.flash > 0) n.flash = Math.max(0, n.flash - dt * 0.9);
        n.ripples = n.ripples.map((r) => r + dt).filter((r) => r < 1.6);
      }
      this.dirty = true;
    }
    if (!this.dirty) return;
    this.dirty = false;
    this.draw();
  }

  private updatePulses(dt: number) {
    // ambient + status-driven spawning
    for (const s of this.strands) {
      if (s.kind === 'ghost') continue;
      const run = (s.a.status === 'running' ? 1 : 0) + (s.b.status === 'running' ? 1 : 0);
      const act = (s.a.activity + s.b.activity) / 2;
      const rate = (s.core ? 0.035 : 0.02) + act * 0.08 + run * 1.1;
      if (Math.random() < rate * dt) {
        const src = s.b.status === 'running' ? s.b : s.a.status === 'running' ? s.a : Math.random() < 0.5 ? s.a : s.b;
        const rgb = src.kind === 'core' ? HOT : src.rgb;
        this.spawn(s, src === s.a ? 1 : -1, rgb, run ? 1.15 : 0.8);
      }
    }
    const out: Pulse[] = [];
    for (const p of this.pulses) {
      p.t += p.speed * dt;
      if (p.t < 1.12) out.push(p);
      else {
        const dest = p.dir === 1 ? p.s.b : p.s.a;
        dest.flash = Math.min(1.2, dest.flash + 0.12 * p.size);
      }
    }
    this.pulses = out;
  }

  private strandGeom(s: Strand) {
    const ax = s.a.x, ay = s.a.y, bx = s.b.x, by = s.b.y;
    const len = Math.hypot(bx - ax, by - ay);
    // catenary-ish sag (gravity +y) with a gentle sway
    const sway = this.reduced ? 0 : Math.sin(this.time * 0.7 + s.phase) * 0.012;
    const sag = len * (0.07 + sway);
    const nx = -(by - ay) / (len || 1), ny = (bx - ax) / (len || 1);
    // pick the normal that points "down"-ish, blend with pure gravity
    const sgn = ny >= 0 ? 1 : -1;
    s.cx = (ax + bx) / 2 + (nx * sgn * 0.6) * sag;
    s.cy = (ay + by) / 2 + (ny * sgn * 0.6 + 0.4) * sag;
    s.len = len;
  }

  private draw() {
    const { ctx, dpr, W, H, cam } = this;
    const k = cam.k;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
    // background
    const bg = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, Math.max(W, H) * 0.75);
    bg.addColorStop(0, '#120914'); bg.addColorStop(0.55, '#09060c'); bg.addColorStop(1, '#050307');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);

    // parallax starfield / dust (screen space)
    for (const s of this.stars) {
      const px = ((s.x - cam.x * s.z * k) % W + W) % W;
      const py = ((s.y - cam.y * s.z * k) % H + H) % H;
      const tw = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(this.time * (0.6 + s.z * 3) + s.tw));
      ctx.fillStyle = s.z > 0.25 ? `rgba(255,170,205,${0.32 * tw})` : `rgba(246,233,240,${0.18 * tw})`;
      ctx.fillRect(px, py, s.s, s.s);
    }

    // world transform
    ctx.setTransform(dpr * k, 0, 0, dpr * k, dpr * (W / 2 - cam.x * k), dpr * (H / 2 - cam.y * k));
    const hair = 1 / k;

    // web
    if (this.spokePath && this.webPath) {
      ctx.lineWidth = 0.8 * hair;
      ctx.strokeStyle = 'rgba(255,62,138,0.075)';
      ctx.stroke(this.spokePath);
      ctx.strokeStyle = 'rgba(255,111,174,0.06)';
      ctx.stroke(this.webPath);
    }
    // web glow fade at center
    const cg = ctx.createRadialGradient(0, 0, 0, 0, 0, this.outerR * 0.9);
    cg.addColorStop(0, 'rgba(255,62,138,0.10)'); cg.addColorStop(1, 'rgba(255,62,138,0)');
    ctx.fillStyle = cg; ctx.beginPath(); ctx.arc(0, 0, this.outerR * 0.9, 0, TAU); ctx.fill();

    // strands
    const hov = this.hovered || (this.focusId ? this.byId.get(this.focusId) || null : null);
    const hl = hov ? new Set(this.nodeStrands.get(hov.id) || []) : null;
    for (const s of this.strands) this.strandGeom(s);

    ctx.lineCap = 'round';
    // base strands (batched)
    ctx.beginPath();
    for (const s of this.strands) {
      if (hl?.has(s) || s.kind === 'ghost' || s.a.status === 'running' || s.b.status === 'running') continue;
      ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
    }
    ctx.lineWidth = 1.1 * hair;
    ctx.strokeStyle = hl ? 'rgba(255,111,174,0.10)' : 'rgba(255,111,174,0.22)';
    ctx.stroke();
    // active strands (running endpoints)
    for (const s of this.strands) {
      if (hl?.has(s) || s.kind === 'ghost') continue;
      const runner = s.a.status === 'running' ? s.a : s.b.status === 'running' ? s.b : null;
      if (!runner) continue;
      const breathe = 0.35 + 0.15 * Math.sin(this.time * 3 + runner.phase);
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
      ctx.lineWidth = 1.5 * hair; ctx.strokeStyle = rgba(runner.rgb, hl ? breathe * 0.5 : breathe); ctx.stroke();
    }
    // ghost strand (dashed)
    for (const s of this.strands) if (s.kind === 'ghost') {
      ctx.save(); ctx.setLineDash([4 * hair, 6 * hair]);
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
      ctx.lineWidth = 1 * hair; ctx.strokeStyle = this.hovered === s.b ? 'rgba(255,111,174,0.55)' : 'rgba(255,111,174,0.16)'; ctx.stroke();
      ctx.restore();
    }
    // highlighted strands
    if (hl && hov) {
      for (const s of hl) {
        if (s.kind === 'ghost') continue;
        const other = s.a === hov ? s.b : s.a;
        const g = ctx.createLinearGradient(hov.x, hov.y, other.x, other.y);
        g.addColorStop(0, rgba(hov.rgb, 0.95)); g.addColorStop(1, rgba(other.kind === 'core' ? HOT : other.rgb, 0.5));
        ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.quadraticCurveTo(s.cx, s.cy, s.b.x, s.b.y);
        ctx.lineWidth = 1.8 * hair; ctx.strokeStyle = g; ctx.stroke();
      }
    }

    // pulses (additive)
    ctx.globalCompositeOperation = 'lighter';
    for (const p of this.pulses) {
      const s = p.s;
      const dim = hl && !hl.has(s) ? 0.35 : 1;
      const spr = this.sprite(p.rgb);
      for (let j = 0; j < 4; j++) {
        let t = p.t - j * 0.022;
        if (t < 0 || t > 1) continue;
        if (p.dir === -1) t = 1 - t;
        const u = 1 - t;
        const x = u * u * s.a.x + 2 * u * t * s.cx + t * t * s.b.x;
        const y = u * u * s.a.y + 2 * u * t * s.cy + t * t * s.b.y;
        const sz = (j === 0 ? 14 : 10 - j * 2) * p.size * hair;
        ctx.globalAlpha = (j === 0 ? 1 : 0.55 - j * 0.12) * dim;
        ctx.drawImage(spr, x - sz / 2, y - sz / 2, sz, sz);
      }
    }
    ctx.globalAlpha = 1;

    // node halos (additive)
    for (const n of this.nodes) {
      if (n.kind === 'ghost') continue;
      const breathe = n.status === 'running' ? 1 + 0.22 * Math.sin(this.time * 2.6 + n.phase) : 1 + 0.05 * Math.sin(this.time * 0.9 + n.phase);
      let a = n.kind === 'core' ? 0.75 : 0.22 + n.activity * 0.3 + (n.status === 'running' ? 0.45 : 0) + n.flash * 0.35;
      let rgb = n.kind === 'core' ? PINK : n.rgb;
      if (n.status === 'error') { rgb = RED; a = 0.35 + (Math.random() < 0.08 ? 0.4 : 0) + 0.15 * Math.sin(this.time * 11 + n.phase); }
      const size = (n.kind === 'core' ? 9 : 5.5 + n.flash * 1.5) * n.r * breathe;
      ctx.globalAlpha = Math.min(1, a) * (hl && hov !== n && n.kind !== 'core' ? 0.5 : 1);
      ctx.drawImage(this.haloSprite(rgb), n.x - size / 2, n.y - size / 2, size, size);
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';

    // ripples
    for (const n of this.nodes) for (const r of n.ripples) {
      const u = r / 1.6;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.r + u * 60, 0, TAU);
      ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(n.rgb, 0.5 * (1 - u)); ctx.stroke();
    }

    // nodes
    for (const n of this.nodes) {
      if (n.kind === 'core') this.drawCore(n);
      else if (n.kind === 'ghost') this.drawGhost(n);
      else this.drawProject(n, hov, hl);
    }
    this.positionHoverEl();
  }

  private drawCore(n: SimNode) {
    const { ctx } = this; const hair = 1 / this.cam.k; const t = this.time;
    const hex = (r: number, rot: number) => {
      ctx.beginPath();
      for (let i = 0; i < 6; i++) { const a = rot + (i / 6) * TAU - Math.PI / 2; const x = n.x + Math.cos(a) * r, y = n.y + Math.sin(a) * r; i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }
      ctx.closePath();
    };
    // orbit rings
    ctx.lineWidth = hair;
    for (let i = 0; i < 2; i++) {
      ctx.save(); ctx.setLineDash([2 * hair, 7 * hair]); ctx.lineDashOffset = (i ? -1 : 1) * t * 10;
      ctx.beginPath(); ctx.arc(n.x, n.y, n.r + 14 + i * 12, 0, TAU);
      ctx.strokeStyle = `rgba(255,111,174,${0.32 - i * 0.12})`; ctx.stroke(); ctx.restore();
    }
    hex(n.r, t * 0.15);
    ctx.fillStyle = 'rgba(16,6,14,0.94)'; ctx.fill();
    ctx.lineWidth = 1.6 * hair; ctx.strokeStyle = 'rgba(255,111,174,0.95)'; ctx.stroke();
    hex(n.r * 0.58, -t * 0.3);
    ctx.fillStyle = 'rgba(255,62,138,0.14)'; ctx.fill();
    ctx.lineWidth = hair; ctx.strokeStyle = 'rgba(255,62,138,0.75)'; ctx.stroke();
    // spokes from inner to outer hex
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a1 = t * 0.15 + (i / 6) * TAU - Math.PI / 2, a2 = -t * 0.3 + (i / 6) * TAU - Math.PI / 2;
      ctx.moveTo(n.x + Math.cos(a2) * n.r * 0.58, n.y + Math.sin(a2) * n.r * 0.58); ctx.lineTo(n.x + Math.cos(a1) * n.r, n.y + Math.sin(a1) * n.r);
    }
    ctx.strokeStyle = 'rgba(255,62,138,0.35)'; ctx.stroke();
    const p = 0.8 + 0.2 * Math.sin(t * 2.2);
    ctx.globalCompositeOperation = 'lighter';
    const s = 26 * p;
    ctx.drawImage(this.sprite(PINK), n.x - s / 2, n.y - s / 2, s, s);
    ctx.globalCompositeOperation = 'source-over';
    // label
    if (this.cam.k > 0.35) {
      ctx.font = `600 ${8.5}px Orbitron, sans-serif`;
      (ctx as any).letterSpacing = '3px';
      ctx.textAlign = 'center'; ctx.textBaseline = 'top';
      ctx.fillStyle = 'rgba(255,111,174,0.7)';
      ctx.fillText('NXEON CORE', n.x + 1.5, n.y + n.r + 32);
      (ctx as any).letterSpacing = '0px';
    }
  }

  private drawGhost(n: SimNode) {
    const { ctx } = this; const hair = 1 / this.cam.k;
    const on = this.hovered === n;
    ctx.save();
    ctx.setLineDash([3 * hair, 3.5 * hair]); ctx.lineDashOffset = -this.time * 6;
    ctx.beginPath(); ctx.arc(n.x, n.y, n.r + (on ? 2 : 0), 0, TAU);
    ctx.fillStyle = on ? 'rgba(255,62,138,0.12)' : 'rgba(10,6,12,0.85)'; ctx.fill();
    ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = on ? 'rgba(255,111,174,0.95)' : 'rgba(255,111,174,0.45)'; ctx.stroke();
    ctx.restore();
    ctx.beginPath();
    ctx.moveTo(n.x - 5, n.y); ctx.lineTo(n.x + 5, n.y); ctx.moveTo(n.x, n.y - 5); ctx.lineTo(n.x, n.y + 5);
    ctx.lineWidth = 1.6 * hair; ctx.strokeStyle = on ? '#ff6fae' : 'rgba(255,111,174,0.7)'; ctx.stroke();
    if (this.cam.k > 0.4 || on) this.label(n, 'New project', on ? 1 : 0.55, on ? '#ff6fae' : undefined);
  }

  private drawProject(n: SimNode, hov: SimNode | null, hl: Set<Strand> | null) {
    const { ctx } = this; const hair = 1 / this.cam.k; const t = this.time;
    const isHov = hov === n;
    const dim = hl && !isHov && ![...hl].some((s) => s.a === n || s.b === n) ? 0.45 : 1;
    let rgb = n.rgb;
    let flick = 1;
    if (n.status === 'error') { rgb = Math.random() < 0.5 ? RED : WARM; flick = 0.6 + 0.4 * (Math.random() < 0.1 ? 0.2 : 1) * (0.75 + 0.25 * Math.sin(t * 13 + n.phase)); }
    const breathe = n.status === 'running' ? 1 + 0.06 * Math.sin(t * 2.6 + n.phase) : 1;
    const r = n.r * breathe + (isHov ? 2.5 : 0);
    ctx.globalAlpha = dim * flick;
    // body
    ctx.beginPath(); ctx.arc(n.x, n.y, r, 0, TAU);
    const g = ctx.createRadialGradient(n.x, n.y - r * 0.4, 0, n.x, n.y, r);
    g.addColorStop(0, rgba(rgb, 0.28)); g.addColorStop(1, 'rgba(12,7,14,0.96)');
    ctx.fillStyle = g; ctx.fill();
    ctx.lineWidth = (isHov ? 2 : 1.4) * hair; ctx.strokeStyle = rgba(rgb, 0.55 + n.activity * 0.3 + (isHov ? 0.3 : 0) + n.flash * 0.2); ctx.stroke();
    // inner ring
    ctx.beginPath(); ctx.arc(n.x, n.y, r - 3.5, 0, TAU); ctx.lineWidth = 0.7 * hair; ctx.strokeStyle = rgba(rgb, 0.22); ctx.stroke();
    // running: orbiters + arc sweep
    if (n.status === 'running' && !this.reduced) {
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, t * 2.4 + n.phase, t * 2.4 + n.phase + Math.PI * 0.7);
      ctx.lineWidth = 1.5 * hair; ctx.strokeStyle = rgba(rgb, 0.9); ctx.stroke();
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, t * 2.4 + n.phase + Math.PI, t * 2.4 + n.phase + Math.PI * 1.35);
      ctx.strokeStyle = rgba(rgb, 0.45); ctx.stroke();
      for (let i = 0; i < 3; i++) {
        const a = -t * 1.3 + n.phase + (i / 3) * TAU;
        ctx.beginPath(); ctx.arc(n.x + Math.cos(a) * (r + 10), n.y + Math.sin(a) * (r + 10), 1.4, 0, TAU);
        ctx.fillStyle = rgba(rgb, 0.85); ctx.fill();
      }
    } else if (n.status === 'running') {
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(rgb, 0.7); ctx.stroke();
    }
    if (n.status === 'error') {
      ctx.save(); ctx.setLineDash([2 * hair, 3 * hair]);
      ctx.beginPath(); ctx.arc(n.x, n.y, r + 5, 0, TAU); ctx.lineWidth = 1.2 * hair; ctx.strokeStyle = rgba(RED, 0.75); ctx.stroke(); ctx.restore();
    }
    // icon
    const img = this.icons.get(n.data?.icon || '') || this.icons.get('boxes');
    const is = r * 1.05;
    if (img && img.complete && img.naturalWidth) {
      ctx.globalAlpha = dim * flick * 0.92;
      ctx.drawImage(img, n.x - is / 2, n.y - is / 2, is, is);
    } else {
      ctx.fillStyle = rgba(rgb, 0.9); ctx.font = `600 ${r * 0.8}px Orbitron, sans-serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText((n.label[0] || '?').toUpperCase(), n.x, n.y + 0.5);
    }
    // pin marker
    if (n.pinned && isHov) { ctx.beginPath(); ctx.arc(n.x + r * 0.72, n.y - r * 0.72, 2, 0, TAU); ctx.fillStyle = '#ff6fae'; ctx.fill(); }
    ctx.globalAlpha = 1;
    if (this.cam.k > 0.45 || isHov) this.label(n, n.label, isHov ? 1 : 0.72 * dim);
  }

  private label(n: SimNode, text: string, alpha: number, color?: string) {
    const { ctx } = this;
    const k = this.cam.k;
    // keep labels at a constant-ish screen size
    const px = Math.max(9, Math.min(13, 11.5 / Math.sqrt(Math.max(0.3, k)))) ;
    ctx.save();
    ctx.translate(n.x, n.y + n.r + 6 / k + 2);
    ctx.scale(1 / k, 1 / k);
    ctx.font = `500 ${px * Math.min(1.25, Math.max(0.85, k))}px "Space Grotesk", sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'top';
    const s = text.length > 24 ? text.slice(0, 23) + '…' : text;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = 'rgba(7,5,10,0.75)';
    const w = ctx.measureText(s).width;
    ctx.fillRect(-w / 2 - 4, 1, w + 8, px * 1.35 + 2);
    ctx.fillStyle = color || '#f6e9f0';
    ctx.fillText(s, 0, 2);
    ctx.restore();
  }

  private positionHoverEl() {
    const el = this.hoverEl;
    if (!el) return;
    const n = this.hovered && this.hovered.kind === 'project' ? this.hovered : null;
    if (!n) return;
    const p = this.screenPos(n);
    const r = n.r * this.cam.k;
    const w = el.offsetWidth || 260, h = el.offsetHeight || 120;
    let x = p.x + r + 16, y = p.y - h / 2;
    if (x + w > this.W - 12) x = p.x - r - 16 - w;
    y = Math.max(12, Math.min(this.H - h - 12, y));
    el.style.transform = `translate3d(${Math.round(x)}px, ${Math.round(y)}px, 0)`;
  }
}

