import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { List, LocateFixed, Minus, Plus, RotateCcw, Search, X, Orbit } from 'lucide-react';
import { Badge, Button, IconButton, Input, Kbd, StatusDot, cn, modKey } from '@/components/ui';
import { PROJECT_ICONS, ProjectBadge } from '@/components/ProjectIcon';
import { useProjects } from '@/stores/projects';
import { useUI } from '@/stores/ui';
import { live } from '@/lib/ws';
import { timeAgo } from '@/lib/format';
import type { GraphNode } from '@/lib/types';
import { NexusEngine, type NodeStatus, type SimNode } from './engine';

/** Renders lucide icons once (hidden) and converts them into <img> sprites for the canvas. */
function useIconSprites(onReady: (m: Map<string, HTMLImageElement>) => void) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const host = ref.current;
    if (!host) return;
    const map = new Map<string, HTMLImageElement>();
    host.querySelectorAll<SVGSVGElement>('svg[data-icon]').forEach((svg) => {
      const name = svg.getAttribute('data-icon')!;
      const clone = svg.cloneNode(true) as SVGSVGElement;
      clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
      clone.setAttribute('width', '64'); clone.setAttribute('height', '64');
      const img = new Image();
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(clone.outerHTML);
      map.set(name, img);
    });
    onReady(map);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <div ref={ref} aria-hidden className="hidden">
      {Object.entries(PROJECT_ICONS).map(([n, I]) => <I key={n} data-icon={n} color="#f6e9f0" strokeWidth={1.75} />)}
    </div>
  );
}

function toNodeStatus(s: string): NodeStatus {
  return s === 'running' || s === 'queued' ? 'running' : s === 'error' ? 'error' : 'idle';
}

export default function NexusPage() {
  const nav = useNavigate();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hoverRef = useRef<HTMLDivElement>(null);
  const engineRef = useRef<NexusEngine | null>(null);
  const { graph, loadGraph, projects, load, loaded } = useProjects();
  const [hover, setHover] = useState<SimNode | null>(null);
  const [warp, setWarp] = useState<string | null>(null);
  const [listOpen, setListOpen] = useState(() => { try { return localStorage.getItem('nx.nexus.list') === '1'; } catch { return false; } });
  const [statuses, setStatuses] = useState<Record<string, NodeStatus>>({});
  const iconEl = useIconSprites((m) => engineRef.current?.setIcons(m) ?? (pendingIcons.current = m));
  const pendingIcons = useRef<Map<string, HTMLImageElement> | null>(null);

  // engine lifecycle
  useEffect(() => {
    const c = canvasRef.current!;
    const eng = new NexusEngine(c, {
      onHover: (n) => setHover(n),
      onGhost: () => useUI.getState().setNewProject(true),
      onOpen: (n) => openProject(n.data!),
    });
    engineRef.current = eng;
    eng.setHoverElement(hoverRef.current);
    if (pendingIcons.current) eng.setIcons(pendingIcons.current);
    const g = useProjects.getState().graph;
    if (g) eng.setGraph(g);
    return () => { eng.dispose(); engineRef.current = null; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // data
  useEffect(() => {
    loadGraph(); if (!loaded) load();
    const t = window.setInterval(() => loadGraph(), 60_000);
    return () => window.clearInterval(t);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (graph) engineRef.current?.setGraph(graph); }, [graph]);

  // live: subscribe to every project in the graph
  const ids = useMemo(() => (graph?.nodes || []).filter((n) => n.id !== 'core').map((n) => n.id).sort().join(','), [graph]);
  useEffect(() => {
    if (!ids) return;
    const offs = ids.split(',').map((id) => live.subProject(id));
    return () => offs.forEach((f) => f());
  }, [ids]);
  useEffect(() => live.on((m) => {
    const eng = engineRef.current;
    if (m.t === 'graph_pulse') eng?.pulse(m.projectId, m.intensity);
    else if (m.t === 'run_status') {
      const s = toNodeStatus(m.status);
      eng?.setStatus(m.projectId, s);
      setStatuses((x) => ({ ...x, [m.projectId]: s }));
      if (m.status === 'done' || m.status === 'error') window.setTimeout(() => loadGraph(), 1500);
    }
  }), [loadGraph]);

  // keyboard: "/" focuses list search, "l" toggles list
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || e.metaKey || e.ctrlKey) return;
      if (e.key === 'l') toggleList();
      else if (e.key === 'n') useUI.getState().setNewProject(true);
      else if (e.key === '0') engineRef.current?.fit();
      else if (e.key === '+' || e.key === '=') engineRef.current?.zoomBy(1.25);
      else if (e.key === '-') engineRef.current?.zoomBy(0.8);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  const toggleList = () => setListOpen((o) => { try { localStorage.setItem('nx.nexus.list', o ? '0' : '1'); } catch {} return !o; });

  function openProject(n: GraphNode) {
    if (!n?.slug) return;
    setWarp(n.color || '#ff3e8a');
    const go = () => nav(`/p/${n.slug}`);
    if (engineRef.current) engineRef.current.flyTo(n.id, go); else go();
  }

  const nodes = (graph?.nodes || []).filter((n) => n.id !== 'core');
  const nodeStatus = (n: GraphNode) => statuses[n.id] || n.status;
  const runningCount = nodes.filter((n) => nodeStatus(n) === 'running').length;
  const hp = hover?.data ? projects.find((p) => p.id === hover.data!.id) : null;
  const hs = hover?.data ? nodeStatus(hover.data) : 'idle';

  return (
    <div className="absolute inset-0 overflow-hidden bg-bg">
      {iconEl}
      <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" aria-label="Project network. Use the list view for keyboard navigation." role="img" />
      {/* CRT vignette + scanlines */}
      <div className="pointer-events-none absolute inset-0 [background:radial-gradient(ellipse_at_center,transparent_45%,rgba(0,0,0,0.75)_100%)]" />
      <div className="pointer-events-none absolute inset-0 opacity-60 [background:repeating-linear-gradient(to_bottom,rgba(255,255,255,0.02)_0_1px,transparent_1px_3px)]" />

      {/* heading */}
      <div className={cn('pointer-events-none absolute top-5 transition-[left] duration-300', listOpen ? 'left-[332px]' : 'left-5')}>
        <div className="font-display text-[11px] font-semibold tracking-[0.32em] text-pink/90 nx-text-glow">THE NEXUS</div>
        <div className="mt-1 font-mono text-[11px] text-muted">
          {nodes.length} project{nodes.length === 1 ? '' : 's'}
          {runningCount > 0 && <span className="text-hot"> · {runningCount} running</span>}
        </div>
      </div>

      {/* top-right actions */}
      <div className="absolute right-4 top-4 flex items-center gap-2">
        <Button size="sm" variant="primary" icon={<Plus size={14} />} onClick={() => useUI.getState().setNewProject(true)}>New project</Button>
      </div>

      {/* controls */}
      <div className="absolute bottom-4 right-4 flex flex-col gap-1 rounded-xl border border-line bg-panel/80 p-1 backdrop-blur-md">
        <IconButton size="sm" icon={<Plus size={15} />} label="Zoom in" shortcut="+" tooltipSide="left" onClick={() => engineRef.current?.zoomBy(1.3)} />
        <IconButton size="sm" icon={<Minus size={15} />} label="Zoom out" shortcut="−" tooltipSide="left" onClick={() => engineRef.current?.zoomBy(0.77)} />
        <div className="mx-1 h-px bg-line" />
        <IconButton size="sm" icon={<LocateFixed size={15} />} label="Recenter (double-click)" shortcut="0" tooltipSide="left" onClick={() => engineRef.current?.fit()} />
        <IconButton size="sm" icon={<RotateCcw size={14} />} label="Reset layout" tooltipSide="left" onClick={() => engineRef.current?.resetLayout()} />
      </div>
      <div className="absolute bottom-4 left-1/2 hidden -translate-x-1/2 items-center gap-3 font-mono text-[10.5px] text-muted/60 md:flex pointer-events-none">
        <span>drag to pan · scroll to zoom · drag nodes to arrange</span>
        <span className="flex items-center gap-1"><Kbd>{modKey}K</Kbd> jump</span>
      </div>

      {/* list toggle */}
      <div className={cn('absolute bottom-4 transition-[left] duration-300', listOpen ? 'left-[332px]' : 'left-4')}>
        <IconButton variant="secondary" icon={<List size={15} />} label={listOpen ? 'Hide project list' : 'Show project list'} shortcut="L" active={listOpen} onClick={toggleList} tooltipSide="right" />
      </div>
      <ProjectList
        open={listOpen} onClose={toggleList} nodes={nodes} statusOf={nodeStatus}
        onFocus={(id) => engineRef.current?.setFocus(id)} onOpen={openProject}
        roles={Object.fromEntries(projects.map((p) => [p.id, p.myRole]))}
        descs={Object.fromEntries(projects.map((p) => [p.id, p.description]))}
      />

      {/* empty hint */}
      {graph && nodes.length === 0 && (
        <div className="pointer-events-none absolute left-1/2 top-[calc(50%+90px)] -translate-x-1/2 text-center animate-fade-in">
          <div className="text-sm text-ink/90">The web is empty.</div>
          <div className="mt-1 text-xs text-muted">Click the <span className="text-hot">+</span> node to spin your first project.</div>
        </div>
      )}

      {/* hover card (positioned by the engine each frame) */}
      <div ref={hoverRef} className={cn('pointer-events-none absolute left-0 top-0 w-[270px] transition-opacity duration-150', hover?.data ? 'opacity-100' : 'opacity-0')} style={{ willChange: 'transform' }}>
        {hover?.data && (
          <div className="nx-glass rounded-xl p-3.5 animate-pop-in">
            <div className="absolute inset-x-6 -top-px h-px" style={{ background: `linear-gradient(90deg, transparent, ${hover.data.color}, transparent)` }} />
            <div className="flex items-start gap-3">
              <ProjectBadge name={hover.data.icon} color={hover.data.color} size={34} />
              <div className="min-w-0 flex-1">
                <div className="truncate font-medium text-ink">{hover.data.name}</div>
                <div className="font-mono text-[10.5px] text-muted">/p/{hover.data.slug}</div>
              </div>
            </div>
            {hp?.description && <p className="mt-2.5 line-clamp-3 text-xs leading-relaxed text-muted">{hp.description}</p>}
            <div className="mt-3 flex flex-wrap items-center gap-1.5">
