import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { List, LocateFixed, Minus, Plus, RotateCcw, Search, X, Orbit } from 'lucide-react';
import { Badge, Button, IconButton, Input, Kbd, StatusDot, cn, modKey } from '@/components/ui';
import { PROJECT_ICONS, ProjectBadge } from '@/components/ProjectIcon';
import { useProjects } from '@/stores/projects';
import { useUI } from '@/stores/ui';
import { live } from '@/lib/ws';
import { timeAgo } from '@/lib/format';
import type { GraphNode } from '@/lib/types';
import { NexusEngine, type NodeStatus, type SimNode } from './engine';

/** Renders lucide icons once (hidden) and converts them into <img> sprites for the canvas. */
function useIconSprites(onReady: (m: Map<string, HTMLImageElement>) => void) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const host = ref.current;
    if (!host) return;
    const map = new Map<string, HTMLImageElement>();
    host.querySelectorAll<SVGSVGElement>('svg[data-icon]').forEach((svg) => {
      const name = svg.getAttribute('data-icon')!;
      const clone = svg.cloneNode(true) as SVGSVGElement;
      clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
      clone.setAttribute('width', '64'); clone.setAttribute('height', '64');
      const img = new Image();
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(clone.outerHTML);
      map.set(name, img);
    });
    onReady(map);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  return (
    <div ref={ref} aria-hidden className="hidden">
      {Object.entries(PROJECT_ICONS).map(([n, I]) => <I key={n} data-icon={n} color="#f6e9f0" strokeWidth={1.75} />)}
    </div>
  );
}

function toNodeStatus(s: string): NodeStatus {
  return s === 'running' || s === 'queued' ? 'running' : s === 'error' ? 'error' : 'idle';
}

export default function NexusPage() {
  const nav = useNavigate();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hoverRef = useRef<HTMLDivElement>(null);
  const engineRef = useRef<NexusEngine | null>(null);
  const { graph, loadGraph, projects, load, loaded } = useProjects();
  const [hover, setHover] = useState<SimNode | null>(null);
  const [warp, setWarp] = useState<string | null>(null);
  const [listOpen, setListOpen] = useState(() => { try { return localStorage.getItem('nx.nexus.list') === '1'; } catch { return false; } });
  const [statuses, setStatuses] = useState<Record<string, NodeStatus>>({});
  const iconEl = useIconSprites((m) => engineRef.current?.setIcons(m) ?? (pendingIcons.current = m));
  const pendingIcons = useRef<Map<string, HTMLImageElement> | null>(null);

  // engine lifecycle
  useEffect(() => {
    const c = canvasRef.current!;
    const eng = new NexusEngine(c, {
      onHover: (n) => setHover(n),
      onGhost: () => useUI.getState().setNewProject(true),
      onOpen: (n) => openProject(n.data!),
    });
    engineRef.current = eng;
    eng.setHoverElement(hoverRef.current);
    if (pendingIcons.current) eng.setIcons(pendingIcons.current);
    const g = useProjects.getState().graph;
    if (g) eng.setGraph(g);
    return () => { eng.dispose(); engineRef.current = null; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // data
  useEffect(() => {
    loadGraph(); if (!loaded) load();
    const t = window.setInterval(() => loadGraph(), 60_000);
    return () => window.clearInterval(t);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (graph) engineRef.current?.setGraph(graph); }, [graph]);

  // live: subscribe to every project in the graph
  const ids = useMemo(() => (graph?.nodes || []).filter((n) => n.id !== 'core').map((n) => n.id).sort().join(','), [graph]);
  useEffect(() => {
    if (!ids) return;
    const offs = ids.split(',').map((id) => live.subProject(id));
    return () => offs.forEach((f) => f());
  }, [ids]);
  useEffect(() => live.on((m) => {
    const eng = engineRef.current;
    if (m.t === 'graph_pulse') eng?.pulse(m.projectId, m.intensity);
    else if (m.t === 'run_status') {
      const s = toNodeStatus(m.status);
      eng?.setStatus(m.projectId, s);
      setStatuses((x) => ({ ...x, [m.projectId]: s }));
      if (m.status === 'done' || m.status === 'error') window.setTimeout(() => loadGraph(), 1500);
    }
  }), [loadGraph]);

  // keyboard: "/" focuses list search, "l" toggles list
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || e.metaKey || e.ctrlKey) return;
      if (e.key === 'l') toggleList();
      else if (e.key === 'n') useUI.getState().setNewProject(true);
      else if (e.key === '0') engineRef.current?.fit();
      else if (e.key === '+' || e.key === '=') engineRef.current?.zoomBy(1.25);
      else if (e.key === '-') engineRef.current?.zoomBy(0.8);
