        <IconButton size="sm" icon={<Plus size={15} />} label="Zoom in" shortcut="+" tooltipSide="left" onClick={() => engineRef.current?.zoomBy(1.3)} />
        <IconButton size="sm" icon={<Minus size={15} />} label="Zoom out" shortcut="−" tooltipSide="left" onClick={() => engineRef.current?.zoomBy(0.77)} />
        <div className="mx-1 h-px bg-line" />
        <IconButton size="sm" icon={<LocateFixed size={15} />} label="Recenter (double-click)" shortcut="0" tooltipSide="left" onClick={() => engineRef.current?.fit()} />
        <IconButton size="sm" icon={<RotateCcw size={14} />} label="Reset layout" tooltipSide="left" onClick={() => engineRef.current?.resetLayout()} />
      </div>
      <div className="absolute bottom-4 left-1/2 hidden -translate-x-1/2 items-center gap-3 font-mono text-[10.5px] text-muted/60 md:flex pointer-events-none">
