      {/* hover card (positioned by the engine each frame) */}
      <div ref={hoverRef} className={cn('pointer-events-none absolute left-0 top-0 w-[270px] transition-opacity duration-150', hover?.data ? 'opacity-100' : 'opacity-0')} style={{ willChange: 'transform' }}>
        {hover?.data && (
