// Admin API client + adapters. Every /api/admin/* call goes through here so response-shape fixes live in one place.
// Adapters accept a few plausible shapes (bare arrays, {items}, {users}, snake/camel variants) and normalize them.
import { api } from '@/lib/api';
import type { Mode, ProjectRole } from '@/shared/protocol';
import type { ModelInfo, User } from '@/lib/types';

// ---------- helpers ----------
const arr = <T = any>(r: any, ...keys: string[]): T[] => {
  if (Array.isArray(r)) return r;
  for (const k of [...keys, 'items', 'data', 'rows']) if (Array.isArray(r?.[k])) return r[k];
  return [];
};
const num = (...v: any[]) => { for (const x of v) if (x != null && isFinite(Number(x))) return Number(x); return 0; };
const qs = (o: Record<string, any>) => {
  const p = new URLSearchParams();
  for (const [k, v] of Object.entries(o)) if (v !== undefined && v !== null && v !== '') p.set(k, String(v));
  const s = p.toString();
  return s ? `?${s}` : '';
};
const toMs = (v: any) => (typeof v === 'number' ? (v < 1e12 ? v * 1000 : v) : Date.parse(v));

// ---------- overview ----------
export interface Overview {
  activeUsers: number; runsToday: number; tokensToday: number; costToday: number; errorRate: number; activeRuns: number; reqPerMin: number;
  usersTotal?: number; projectsTotal?: number;
}
export async function getOverview(): Promise<Overview> {
  const r = await api.get<any>('/admin/overview');
  const o = r?.overview ?? r ?? {};
  return {
    activeUsers: num(o.activeUsers, o.active_users),
    runsToday: num(o.runsToday, o.runs_today),
    tokensToday: num(o.tokensToday, o.tokens_today),
    costToday: num(o.costToday, o.costUsdToday, o.cost, o.cost_today),
    errorRate: num(o.errorRate, o.error_rate),
    activeRuns: num(o.activeRuns, o.active_runs),
    reqPerMin: num(o.reqPerMin, o.requestsPerMin, o.req_per_min, o.rpm),
    usersTotal: o.usersTotal ?? o.users_total,
    projectsTotal: o.projectsTotal ?? o.projects_total,
  };
}

// ---------- timeseries ----------
export type Metric = 'tokens' | 'runs' | 'requests' | 'cost';
export type Range = '24h' | '7d' | '30d';
export type GroupBy = 'user' | 'project' | 'model';
export interface Series { rows: Array<{ ts: number } & Record<string, number>>; keys: string[]; labels: Record<string, string>; totals: { key: string; label: string; value: number }[] }

/**
 * Accepts:
 *  {points:[{ts|t|bucket, value|v|count}]}                      (ungrouped)
 *  {series:[{key|id|name, label?, points:[{ts, value}]}]}       (grouped)
 *  [{ts, value}] or [{ts, key, value}] (long format)
 */
export async function getTimeseries(metric: Metric, range: Range, groupBy?: GroupBy): Promise<Series> {
  const r = await api.get<any>(`/admin/timeseries${qs({ metric, range, groupBy })}`);
  const rowsByTs = new Map<number, any>();
  const labels: Record<string, string> = {};
  const put = (ts: any, key: string, v: any) => {
    const t = toMs(ts);
    if (!isFinite(t)) return;
    const row = rowsByTs.get(t) || { ts: t };
    row[key] = (row[key] || 0) + num(v);
    rowsByTs.set(t, row);
  };
  const ptTs = (p: any) => p.ts ?? p.t ?? p.bucket ?? p.time ?? p.date;
  const ptV = (p: any) => p.value ?? p.v ?? p.count ?? p[metric];
  if (Array.isArray(r?.series)) {
    for (const s of r.series) {
      const key = String(s.key ?? s.id ?? s.name ?? 'value');
      labels[key] = s.label ?? s.name ?? key;
      for (const p of arr(s.points ?? s.data)) put(ptTs(p), key, ptV(p));
    }
  } else {
    const pts = arr(r, 'points');
    for (const p of pts) {
      const key = p.key ?? p.group ?? p.groupKey;
      if (key != null) { labels[String(key)] = p.label ?? String(key); put(ptTs(p), String(key), ptV(p)); }
      else put(ptTs(p), 'value', ptV(p));
    }
    if (!Object.keys(labels).length) labels.value = metric;
  }
  const keys = Object.keys(labels);
  const rows = [...rowsByTs.values()].sort((a, b) => a.ts - b.ts).map((row) => { for (const k of keys) row[k] ??= 0; return row; });
  const totals = keys.map((k) => ({ key: k, label: labels[k], value: rows.reduce((s, x) => s + (x[k] || 0), 0) })).sort((a, b) => b.value - a.value);
  return { rows, keys, labels, totals };
}

