  claudeAuth: { set: boolean; masked: string | null; kind?: 'oauth' | 'apiKey' | string | null; updatedAt?: string | null };
}
export async function getSettings(): Promise<AdminSettings> {
  const r = await api.get<any>('/admin/settings');
  const s = r?.settings ?? r ?? {};
  const ca = s.claudeAuth ?? s.claudeAuthToken ?? {};
  return {
    models: arr(s.models),
    defaultModel: s.defaultModel ?? s.default_model ?? '',
    globalDailyTokenCap: s.globalDailyTokenCap ?? s.global_daily_token_cap ?? null,
    claudeAuth: typeof ca === 'string'
      ? { set: !!ca, masked: ca }
      : { set: !!(ca.set ?? ca.masked), masked: ca.masked ?? null, kind: ca.kind ?? ca.mode ?? null, updatedAt: ca.updatedAt ?? null },
  };
}
/** Only send what changed. claudeAuthToken is write-only (empty string clears it). */
export const saveSettings = (patch: Partial<Omit<AdminSettings, 'claudeAuth'>> & { claudeAuthToken?: string }) => api.put('/admin/settings', patch);

