import { useCallback, useEffect, useRef, useState, type ReactNode } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';
import { Button, IconButton, Tabs, cn } from '@/components/ui';
import type { Range } from './api';

/** Fetch with loading/error state; optional polling interval (ms). Pauses while tab hidden. */
export function useQuery<T>(fn: () => Promise<T>, deps: unknown[] = [], pollMs?: number) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const fnRef = useRef(fn); fnRef.current = fn;
  const seq = useRef(0);
  const run = useCallback(async (quiet = false) => {
    const my = ++seq.current;
    if (!quiet) setLoading(true);
    try { const d = await fnRef.current(); if (my === seq.current) { setData(d); setError(null); } }
    catch (e: any) { if (my === seq.current) setError(e?.message || 'Request failed'); }
    finally { if (my === seq.current) setLoading(false); }
  }, []);
  useEffect(() => { run(); }, deps); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!pollMs) return;
    const t = window.setInterval(() => { if (!document.hidden) run(true); }, pollMs);
    return () => window.clearInterval(t);
  }, [pollMs, run]);
  return { data, error, loading, reload: run, setData };
}

export function PageHeader({ title, description, actions }: { title: ReactNode; description?: ReactNode; actions?: ReactNode }) {
  return (
    <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
      <div>
        <h1 className="text-lg font-semibold text-ink">{title}</h1>
        {description && <p className="mt-0.5 text-sm text-muted">{description}</p>}
      </div>
      {actions && <div className="flex items-center gap-2">{actions}</div>}
    </div>
  );
}

export function Card({ title, actions, children, className, bodyClassName }: { title?: ReactNode; actions?: ReactNode; children: ReactNode; className?: string; bodyClassName?: string }) {
  return (
    <section className={cn('nx-panel flex min-w-0 flex-col', className)}>
      {(title || actions) && (
        <div className="flex items-center justify-between gap-2 border-b border-line/70 px-4 py-2.5">
          <div className="nx-label">{title}</div>
          {actions}
        </div>
      )}
      <div className={cn('min-w-0 flex-1 p-4', bodyClassName)}>{children}</div>
    </section>
  );
}

export function Kpi({ label, value, sub, accent, icon }: { label: string; value: ReactNode; sub?: ReactNode; accent?: boolean; icon?: ReactNode }) {
  return (
    <div className={cn('nx-panel relative overflow-hidden px-4 py-3.5', accent && 'border-pink/30')}>
      {accent && <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-pink to-transparent" />}
      <div className="flex items-center justify-between">
        <div className="nx-label">{label}</div>
        {icon && <div className={accent ? 'text-pink' : 'text-muted/70'}>{icon}</div>}
      </div>
      <div className={cn('mt-1.5 font-mono text-2xl tabular', accent ? 'text-hot' : 'text-ink')}>{value}</div>
      {sub && <div className="mt-0.5 text-[11px] text-muted">{sub}</div>}
    </div>
  );
}

export function ErrorNote({ error, onRetry }: { error: string; onRetry?: () => void }) {
  return (
    <div className="flex items-center gap-3 rounded-lg border border-bad/30 bg-bad/[0.06] px-3 py-2.5 text-sm text-bad">
      <AlertTriangle size={15} /><span className="flex-1">{error}</span>
      {onRetry && <Button size="xs" variant="ghost" onClick={onRetry}>Retry</Button>}
    </div>
  );
}

export function RangePicker({ value, onChange }: { value: Range; onChange: (r: Range) => void }) {
  return <Tabs variant="pill" size="sm" value={value} onChange={onChange} items={[{ value: '24h', label: '24h' }, { value: '7d', label: '7d' }, { value: '30d', label: '30d' }]} />;
}

export function RefreshButton({ onClick, loading }: { onClick: () => void; loading?: boolean }) {
  return <IconButton size="sm" variant="secondary" label="Refresh" icon={<RefreshCw size={13} className={loading ? 'animate-spin' : ''} />} onClick={onClick} />;
}

/** Scroll container for dense tables. */
export function TableWrap({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('nx-panel overflow-auto', className)}>{children}</div>;
}

export function Empty({ children }: { children: ReactNode }) {
  return <div className="px-4 py-10 text-center text-sm text-muted">{children}</div>;
}

export function fmtTick(range: Range) {
  return (ts: number) => {
    const d = new Date(ts);
    return range === '24h' ? d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' }) : d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  };
}
