import { useState } from 'react';
import { Activity, AlertTriangle, Coins, Cpu, Gauge, Radio, Users } from 'lucide-react';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Skeleton, Tabs } from '@/components/ui';
import { fmtCompact, fmtNum, fmtPct, fmtUsd } from '@/lib/format';
import { getOverview, getTimeseries, type GroupBy, type Metric, type Range } from './api';
import { Card, ErrorNote, Kpi, PageHeader, RangePicker, RefreshButton, fmtTick, useQuery } from './common';
import { ChartTooltip, SERIES, chartTheme } from './charts';

const METRICS: { value: Metric; label: string }[] = [
  { value: 'tokens', label: 'Tokens' }, { value: 'runs', label: 'Runs' }, { value: 'requests', label: 'Requests' }, { value: 'cost', label: 'Cost' },
];
const fmtMetric = (m: Metric) => (v: number) => (m === 'cost' ? fmtUsd(v) : m === 'tokens' ? fmtCompact(v, 2) : fmtNum(v));

export default function Overview() {
  const ov = useQuery(getOverview, [], 15_000);
  const [metric, setMetric] = useState<Metric>('tokens');
  const [range, setRange] = useState<Range>('24h');
  const [groupBy, setGroupBy] = useState<GroupBy>('model');
  const total = useQuery(() => getTimeseries(metric, range), [metric, range]);
  const grouped = useQuery(() => getTimeseries(metric === 'requests' ? 'tokens' : metric, range, groupBy), [metric, range, groupBy]);
  const o = ov.data;
  const f = fmtMetric(metric);
  const gm: Metric = metric === 'requests' ? 'tokens' : metric;
  const topKeys = grouped.data ? grouped.data.totals.slice(0, 7).map((t) => t.key) : [];
  const maxTotal = Math.max(1, ...(grouped.data?.totals.map((t) => t.value) || [1]));

  return (
    <div>
      <PageHeader title="Overview" description="Health of the mainframe at a glance." actions={<RefreshButton loading={ov.loading} onClick={() => { ov.reload(); total.reload(); grouped.reload(); }} />} />
      {ov.error && <div className="mb-4"><ErrorNote error={ov.error} onRetry={() => ov.reload()} /></div>}
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-7">
        {o ? (
          <>
            <Kpi label="Active runs" value={o.activeRuns} icon={<Radio size={14} />} accent={o.activeRuns > 0} />
            <Kpi label="Active users" value={o.activeUsers} icon={<Users size={14} />} sub={o.usersTotal != null ? `of ${o.usersTotal}` : 'today'} />
            <Kpi label="Runs today" value={fmtNum(o.runsToday)} icon={<Cpu size={14} />} />
            <Kpi label="Tokens today" value={fmtCompact(o.tokensToday, 2)} icon={<Gauge size={14} />} />
            <Kpi label="Cost today" value={fmtUsd(o.costToday)} icon={<Coins size={14} />} />
            <Kpi label="Error rate" value={fmtPct(o.errorRate > 1 ? o.errorRate / 100 : o.errorRate)} icon={<AlertTriangle size={14} />} sub="runs today" />
            <Kpi label="Req / min" value={fmtNum(Math.round(o.reqPerMin * 10) / 10)} icon={<Activity size={14} />} />
          </>
        ) : Array.from({ length: 7 }, (_, i) => <Skeleton key={i} className="h-[92px]" />)}
      </div>

      <div className="mt-4 flex flex-wrap items-center gap-2">
        <Tabs variant="pill" size="sm" items={METRICS} value={metric} onChange={setMetric} />
        <div className="flex-1" />
        <RangePicker value={range} onChange={setRange} />
      </div>

      <Card className="mt-3" title={`${METRICS.find((m) => m.value === metric)!.label} over time`}
        actions={total.data && <span className="font-mono text-xs text-hot">{f(total.data.totals.reduce((s, t) => s + t.value, 0))}</span>}>
        {total.error ? <ErrorNote error={total.error} /> : !total.data ? <Skeleton className="h-[240px]" /> : (
          <div className="h-[240px]">
            <ResponsiveContainer>
              <AreaChart data={total.data.rows} margin={{ top: 6, right: 6, left: -8, bottom: 0 }}>
                <defs>
                  <linearGradient id="ovfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#ff3e8a" stopOpacity={0.35} /><stop offset="1" stopColor="#ff3e8a" stopOpacity={0} /></linearGradient>
                </defs>
                <CartesianGrid {...chartTheme.grid} />
                <XAxis dataKey="ts" type="number" domain={['dataMin', 'dataMax']} scale="time" tickFormatter={fmtTick(range)} {...chartTheme.axis} minTickGap={40} />
                <YAxis {...chartTheme.axis} tickFormatter={(v) => (metric === 'cost' ? `$${fmtCompact(v)}` : fmtCompact(v))} width={48} />
                <Tooltip cursor={{ stroke: 'rgba(255,62,138,0.4)' }} content={<ChartTooltip format={f} labelFormat={(l) => new Date(l).toLocaleString()} />} />
                {total.data.keys.map((k, i) => (
                  <Area key={k} type="monotone" dataKey={k} name={total.data!.labels[k]} stroke={SERIES[i]} strokeWidth={1.8} fill={i === 0 ? 'url(#ovfill)' : 'transparent'} dot={false} activeDot={{ r: 3.5, fill: '#ff6fae', stroke: '#07050a' }} />
                ))}
              </AreaChart>
            </ResponsiveContainer>
          </div>
        )}
      </Card>

      <div className="mt-4 grid gap-4 lg:grid-cols-[2fr_1fr]">
        <Card
          title={`${gm === 'cost' ? 'Cost' : gm === 'runs' ? 'Runs' : 'Tokens'} by ${groupBy}`}
          actions={<Tabs variant="pill" size="sm" value={groupBy} onChange={setGroupBy} items={[{ value: 'model', label: 'Model' }, { value: 'user', label: 'User' }, { value: 'project', label: 'Project' }]} />}
        >
          {grouped.error ? <ErrorNote error={grouped.error} /> : !grouped.data ? <Skeleton className="h-[260px]" /> : (
            <div className="h-[260px]">
              <ResponsiveContainer>
                <BarChart data={grouped.data.rows} margin={{ top: 6, right: 6, left: -8, bottom: 0 }}>
