import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { Copy, ExternalLink, FileText, Paperclip, ScrollText, Search } from 'lucide-react';
import { Badge, Button, Drawer, EmptyState, Input, Select, Skeleton, toast } from '@/components/ui';
import { fmtBytes, fmtCompact, fmtDateTime, fmtDuration, fmtNum, fmtUsd, timeAgo } from '@/lib/format';
import { listAdminProjects, listPrompts, listUsers, type PromptRow } from './api';
import { ErrorNote, PageHeader, RefreshButton, TableWrap, useQuery } from './common';

const statusTone = (s?: string) => (s === 'done' ? 'ok' : s === 'error' ? 'bad' : s === 'aborted' ? 'warm' : s === 'running' || s === 'queued' ? 'pink' : 'neutral');

export default function Prompts() {
  const [q, setQ] = useState('');
  const [dq, setDq] = useState('');
  const [userId, setUserId] = useState('');
  const [projectId, setProjectId] = useState('');
  const [items, setItems] = useState<PromptRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [open, setOpen] = useState<PromptRow | null>(null);
  const users = useQuery(listUsers, []);
  const projects = useQuery(listAdminProjects, []);

  useEffect(() => { const t = window.setTimeout(() => setDq(q), 300); return () => window.clearTimeout(t); }, [q]);
  const load = async (reset: boolean) => {
    setLoading(true); setError(null);
    try {
      const r = await listPrompts({ q: dq, userId, projectId, cursor: reset ? null : cursor });
      setItems((x) => (reset ? r.items : [...x, ...r.items])); setCursor(r.nextCursor);
    } catch (e: any) { setError(e.message); } finally { setLoading(false); }
  };
  useEffect(() => { load(true); }, [dq, userId, projectId]); // eslint-disable-line react-hooks/exhaustive-deps

  const userOpts = useMemo(() => [{ value: '', label: 'All users' }, ...(users.data || []).map((u) => ({ value: u.id, label: u.email }))], [users.data]);
  const projOpts = useMemo(() => [{ value: '', label: 'All projects' }, ...(projects.data || []).map((p) => ({ value: p.id, label: p.name }))], [projects.data]);

  return (
    <div>
      <PageHeader title="Prompts" description="Every prompt sent to Claude, with attachments, tokens and origin." actions={<RefreshButton loading={loading} onClick={() => load(true)} />} />
      <div className="mb-3 flex flex-wrap gap-2">
        <Input wrapperClassName="flex-1 min-w-[220px]" icon={<Search size={14} />} placeholder="Search prompt text…" value={q} onChange={(e) => setQ(e.target.value)} />
        <Select wrapperClassName="w-[220px]" value={userId} onChange={setUserId} options={userOpts} />
        <Select wrapperClassName="w-[200px]" value={projectId} onChange={setProjectId} options={projOpts} />
      </div>
      {error && <div className="mb-3"><ErrorNote error={error} onRetry={() => load(true)} /></div>}
      <TableWrap>
        <table className="nx-table">
          <thead><tr><th className="w-[110px]">When</th><th>User</th><th>Project</th><th className="w-[40%]">Prompt</th><th>Model</th><th className="text-right">Tokens</th><th>Status</th></tr></thead>
          <tbody>
            {items.map((p) => (
              <tr key={p.id} className="cursor-pointer" onClick={() => setOpen(p)}>
                <td className="whitespace-nowrap font-mono text-xs text-muted" title={fmtDateTime(p.createdAt)}>{timeAgo(p.createdAt)}</td>
                <td className="max-w-[180px] truncate text-[13px]">{p.userEmail || p.userName || p.userId}</td>
                <td className="max-w-[140px] truncate text-[13px] text-ink/85">{p.projectName || p.projectSlug || '—'}</td>
                <td className="max-w-0">
                  <div className="flex items-center gap-2">
                    <span className="truncate text-[13px] text-ink/90">{p.content.replace(/\s+/g, ' ')}</span>
                    {p.attachments.length > 0 && <Badge icon={<Paperclip size={10} />}>{p.attachments.length}</Badge>}
                  </div>
                </td>
                <td className="font-mono text-xs">{p.model || '—'}</td>
                <td className="text-right font-mono text-xs tabular">{p.inputTokens != null ? `${fmtCompact(p.inputTokens)}/${fmtCompact(p.outputTokens || 0)}` : '—'}</td>
                <td>{p.status ? <Badge tone={statusTone(p.status) as any} dot>{p.status}</Badge> : '—'}</td>
