import { useEffect, useMemo, useState } from 'react';
import { Ban, CheckCircle2, Copy, KeyRound, MoreHorizontal, Pencil, Plus, Search, Trash2, UserPlus, Users as UsersIcon, Wand2, X } from 'lucide-react';
import {
  Avatar, Badge, Button, Checkbox, EmptyState, IconButton, Input, Menu, Modal, Popover, Select, Skeleton, Switch, Tabs, toast,
} from '@/components/ui';
import { ProjectBadge } from '@/components/ProjectIcon';
import { api } from '@/lib/api';
import { fmtCompact, fmtNum, timeAgo } from '@/lib/format';
import type { ModelInfo } from '@/lib/types';
import type { Mode, ProjectRole } from '@/shared/protocol';
import { useAuth } from '@/stores/auth';
import {
  createUser, deleteUser, getUserGrants, listAdminProjects, listUsers, setUserGrants, updateUser,
  type AdminProject, type AdminUser, type Grant, type UserInput,
} from './api';
import { ErrorNote, PageHeader, RefreshButton, TableWrap, useQuery } from './common';

const MODES: Mode[] = ['auto', 'edit', 'plan', 'ask'];
const ROLES: ProjectRole[] = ['owner', 'editor', 'viewer'];
function genPassword() {
  const a = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  const b = new Uint32Array(16); crypto.getRandomValues(b);
  return Array.from(b, (x) => a[x % a.length]).join('');
}

export default function UsersPage() {
  const users = useQuery(listUsers, []);
  const me = useAuth((s) => s.user);
  const [q, setQ] = useState('');
  const [edit, setEdit] = useState<AdminUser | 'new' | null>(null);
