  const [del, setDel] = useState<AdminUser | null>(null);
  const list = useMemo(() => {
    const qq = q.toLowerCase();
    return (users.data || []).filter((u) => !qq || u.email.toLowerCase().includes(qq) || (u.name || '').toLowerCase().includes(qq));
  }, [users.data, q]);

  const toggleDisabled = async (u: AdminUser) => {
    try { await updateUser(u.id, { disabled: !u.disabled }); toast.success(u.disabled ? 'User enabled' : 'User disabled'); users.reload(true); }
    catch (e: any) { toast.error(e.message); }
  };

  return (
    <div>
      <PageHeader
        title="Users" description="Accounts, roles, limits and project access."
        actions={<><RefreshButton loading={users.loading} onClick={() => users.reload()} /><Button variant="primary" size="sm" icon={<UserPlus size={14} />} onClick={() => setEdit('new')}>New user</Button></>}
      />
      <div className="mb-3 max-w-sm"><Input icon={<Search size={14} />} placeholder="Search by name or email…" value={q} onChange={(e) => setQ(e.target.value)} /></div>
      {users.error && <div className="mb-3"><ErrorNote error={users.error} onRetry={() => users.reload()} /></div>}
      <TableWrap>
        <table className="nx-table">
          <thead><tr><th>User</th><th>Role</th><th>Status</th><th className="text-right">Daily limit</th><th>Models</th><th>Modes</th><th>Last seen</th><th /></tr></thead>
          <tbody>
            {list.map((u) => (
              <tr key={u.id} className={u.disabled ? 'opacity-55' : ''}>
                <td>
                  <div className="flex items-center gap-2.5">
                    <Avatar name={u.name || u.email} size={28} />
                    <div className="min-w-0">
                      <div className="truncate text-[13.5px]">{u.name || '—'} {u.id === me?.id && <span className="text-[10px] text-pink">(you)</span>}</div>
                      <div className="truncate font-mono text-[11px] text-muted">{u.email}</div>
                    </div>
                  </div>
                </td>
                <td><Badge tone={u.role === 'admin' ? 'pink' : 'neutral'}>{u.role}</Badge></td>
                <td>{u.disabled ? <Badge tone="bad" dot>disabled</Badge> : <Badge tone="ok" dot>active</Badge>}</td>
                <td className="text-right font-mono text-xs tabular">{u.limits?.dailyTokens ? fmtCompact(u.limits.dailyTokens) : <span className="text-muted">∞</span>}</td>
                <td className="text-xs text-muted">{u.limits?.models?.length ? u.limits.models.join(', ') : 'all'}</td>
                <td className="text-xs text-muted">{u.limits?.modes?.length ? u.limits.modes.join(', ') : 'all'}</td>
                <td className="whitespace-nowrap font-mono text-xs text-muted">{timeAgo(u.lastSeenAt)}</td>
                <td className="text-right">
                  <div className="flex justify-end gap-0.5">
                    <IconButton size="sm" icon={<Pencil size={13} />} label="Edit" onClick={() => setEdit(u)} />
                    <Popover align="end" trigger={<IconButton size="sm" icon={<MoreHorizontal size={15} />} label="More" tooltip={false} />}>
                      {(close) => (
                        <Menu onClose={close} items={[
                          { label: 'Reset password', icon: <KeyRound size={14} />, onSelect: () => setReset(u) },
                          { label: u.disabled ? 'Enable account' : 'Disable account', icon: u.disabled ? <CheckCircle2 size={14} /> : <Ban size={14} />, disabled: u.id === me?.id, onSelect: () => toggleDisabled(u) },
                          'sep',
                          { label: 'Delete user', icon: <Trash2 size={14} />, danger: true, disabled: u.id === me?.id, onSelect: () => setDel(u) },
                        ]} />
                      )}
                    </Popover>
                  </div>
                </td>
              </tr>
            ))}
            {users.loading && !users.data && Array.from({ length: 4 }, (_, i) => <tr key={i}><td colSpan={8}><Skeleton className="h-7" /></td></tr>)}
          </tbody>
        </table>
        {users.data && list.length === 0 && <EmptyState compact icon={<UsersIcon size={18} />} title="No users match" />}
      </TableWrap>
      <UserModal user={edit} onClose={() => setEdit(null)} onSaved={() => users.reload(true)} />
      <ResetPasswordModal user={reset} onClose={() => setReset(null)} />
      <Modal open={!!del} onClose={() => setDel(null)} size="sm" title="Delete user?" description={del ? `${del.email} will lose access immediately. Their prompts stay in the log.` : ''}
        footer={<><Button variant="ghost" onClick={() => setDel(null)}>Cancel</Button><Button variant="danger" onClick={async () => {
          try { await deleteUser(del!.id); toast.success('User deleted'); setDel(null); users.reload(true); } catch (e: any) { toast.error(e.message); }
        }}>Delete</Button></>} />
    </div>
  );
}

function ResetPasswordModal({ user, onClose }: { user: AdminUser | null; onClose: () => void }) {
  const [pw, setPw] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (user) setPw(genPassword()); }, [user]);
  const save = async () => {
    setBusy(true);
    try { await updateUser(user!.id, { password: pw }); toast.success('Password reset', { description: 'Share the new password securely.' }); onClose(); }
    catch (e: any) { toast.error(e.message); } finally { setBusy(false); }
  };
  return (
    <Modal open={!!user} onClose={onClose} size="sm" title="Reset password" description={user?.email} icon={<KeyRound size={18} />}
      footer={<><Button variant="ghost" onClick={onClose}>Cancel</Button><Button variant="primary" loading={busy} disabled={pw.length < 8} onClick={save}>Set password</Button></>}>
      <Input mono value={pw} onChange={(e) => setPw(e.target.value)} label="New password" hint="At least 8 characters. Existing sessions are signed out."
        rightSlot={<div className="flex">
          <IconButton size="xs" icon={<Wand2 size={12} />} label="Generate" onClick={() => setPw(genPassword())} />
          <IconButton size="xs" icon={<Copy size={12} />} label="Copy" onClick={() => { navigator.clipboard?.writeText(pw); toast.success('Copied'); }} />
        </div>} className="pr-16" />
    </Modal>
  );
}

function UserModal({ user, onClose, onSaved }: { user: AdminUser | 'new' | null; onClose: () => void; onSaved: () => void }) {
  const isNew = user === 'new';
  const u = isNew ? null : user;
  const [tab, setTab] = useState<'profile' | 'limits' | 'projects'>('profile');
  const [form, setForm] = useState<UserInput>({});
  const [limitStr, setLimitStr] = useState('');
  const [grants, setGrants] = useState<Grant[] | null>(null);
  const [busy, setBusy] = useState(false);
  const models = useQuery(() => api.get<any>('/models').then((r) => (Array.isArray(r) ? r : r?.models || []) as ModelInfo[]), []);
  const projects = useQuery(listAdminProjects, []);

  useEffect(() => {
    if (!user) return;
    setTab('profile');
    setForm(isNew ? { role: 'member', password: genPassword(), limits: {} } : { name: u!.name, email: u!.email, role: u!.role, disabled: !!u!.disabled, limits: { ...u!.limits } });
    setLimitStr(!isNew && u!.limits?.dailyTokens ? String(u!.limits.dailyTokens) : '');
    setGrants(isNew ? [] : null);
    if (!isNew) getUserGrants(u!.id).then(setGrants).catch(() => setGrants([]));
  }, [user]); // eslint-disable-line react-hooks/exhaustive-deps

  const set = (p: Partial<UserInput>) => setForm((f) => ({ ...f, ...p }));
  const lim = form.limits || {};
  const toggleIn = <T extends string>(list: T[] | null | undefined, v: T) => {
    const s = new Set(list || []); s.has(v) ? s.delete(v) : s.add(v); return s.size ? [...s] : null;
  };

  const save = async () => {
    setBusy(true);
    try {
      const dailyTokens = limitStr.trim() ? Math.max(0, Math.round(Number(limitStr.replace(/[_,\s]/g, '')))) : null;
      const body: UserInput = { ...form, limits: { dailyTokens, models: lim.models?.length ? lim.models : null, modes: lim.modes?.length ? lim.modes : null } };
      let id = u?.id;
      if (isNew) { const created = await createUser(body); id = created.id; }
      else { delete body.password; await updateUser(u!.id, body); }
      if (id && grants) await setUserGrants(id, grants.filter((g) => g.projectId));
      toast.success(isNew ? 'User created' : 'User updated', isNew ? { description: `Initial password: ${form.password}`, duration: 0 } : undefined);
      onSaved(); onClose();
    } catch (e: any) { toast.error('Save failed', { description: e.message }); }
    finally { setBusy(false); }
  };

  const projOptions = (projects.data || []).map((p: AdminProject) => ({ value: p.id, label: p.name }));
