import { useState } from 'react';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Badge, Skeleton } from '@/components/ui';
import { fmtNum, timeAgo } from '@/lib/format';
import { getTraffic, type Range } from './api';
import { Card, ErrorNote, PageHeader, RangePicker, RefreshButton, fmtTick, useQuery } from './common';
import { ChartTooltip, chartTheme } from './charts';

const statusColor = (s: string) => (s.startsWith('5') ? '#ff4d6d' : s.startsWith('4') ? '#ffc857' : s.startsWith('3') ? '#b14bff' : '#3dffb5');

export default function Traffic() {
  const [range, setRange] = useState<Range>('24h');
  const t = useQuery(() => getTraffic(range), [range], 30_000);
  const d = t.data;
  const total = d ? d.byStatus.reduce((s, x) => s + x.count, 0) : 0;
  const maxIp = Math.max(1, ...(d?.topIps.map((x) => x.count) || [1]));
  const maxPath = Math.max(1, ...(d?.topPaths.map((x) => x.count) || [1]));
  return (
    <div>
      <PageHeader title="Traffic" description="Who is hitting the box, where, and how it answers." actions={<><RangePicker value={range} onChange={setRange} /><RefreshButton loading={t.loading} onClick={() => t.reload()} /></>} />
      {t.error && <div className="mb-3"><ErrorNote error={t.error} onRetry={() => t.reload()} /></div>}
      <div className="grid gap-4 lg:grid-cols-[2fr_1fr]">
        <Card title="Requests / minute" actions={d && <span className="font-mono text-xs text-hot">{fmtNum(total)} total</span>}>
          {!d ? <Skeleton className="h-[220px]" /> : (
            <div className="h-[220px]">
              <ResponsiveContainer>
                <AreaChart data={d.perMinute} margin={{ top: 6, right: 6, left: -12, bottom: 0 }}>
                  <defs><linearGradient id="trf" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#ff8a5c" stopOpacity={0.35} /><stop offset="1" stopColor="#ff8a5c" stopOpacity={0} /></linearGradient></defs>
                  <CartesianGrid {...chartTheme.grid} />
                  <XAxis dataKey="ts" type="number" scale="time" domain={['dataMin', 'dataMax']} tickFormatter={fmtTick(range)} {...chartTheme.axis} minTickGap={40} />
                  <YAxis {...chartTheme.axis} width={40} />
                  <Tooltip content={<ChartTooltip labelFormat={(l) => new Date(l).toLocaleString()} />} />
                  <Area type="monotone" dataKey="count" name="requests" stroke="#ff8a5c" strokeWidth={1.6} fill="url(#trf)" dot={false} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          )}
        </Card>
        <Card title="Status codes">
          {!d ? <Skeleton className="h-[220px]" /> : (
            <div className="h-[220px]">
              <ResponsiveContainer>
                <BarChart data={[...d.byStatus].sort((a, b) => a.status.localeCompare(b.status))} margin={{ top: 6, right: 6, left: -12, bottom: 0 }}>
                  <CartesianGrid {...chartTheme.grid} />
                  <XAxis dataKey="status" {...chartTheme.axis} />
                  <YAxis {...chartTheme.axis} width={40} />
                  <Tooltip cursor={{ fill: 'rgba(255,62,138,0.05)' }} content={<ChartTooltip format={(v) => fmtNum(v)} />} />
                  <Bar dataKey="count" name="requests" radius={[3, 3, 0, 0]}>{d.byStatus.map((s) => <Cell key={s.status} fill={statusColor(s.status)} />)}</Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </Card>
      </div>
      <div className="mt-4 grid gap-4 lg:grid-cols-2">
        <Card title="Top IPs" bodyClassName="p-0">
          <table className="nx-table">
            <thead><tr><th>IP</th><th>User</th><th className="w-[35%]">Requests</th><th>Last seen</th></tr></thead>
            <tbody>
              {(d?.topIps || []).map((x) => (
                <tr key={x.ip}>
                  <td className="font-mono text-xs">{x.ip}</td>
                  <td className="max-w-[160px] truncate text-xs text-muted">{x.userEmail || '—'}</td>
                  <td><div className="flex items-center gap-2"><div className="h-1 flex-1 rounded-full bg-line/70"><div className="h-full rounded-full bg-pink" style={{ width: `${(x.count / maxIp) * 100}%` }} /></div><span className="w-12 text-right font-mono text-xs tabular">{fmtNum(x.count)}</span></div></td>
                  <td className="font-mono text-xs text-muted">{x.lastSeen ? timeAgo(x.lastSeen) : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {d && d.topIps.length === 0 && <div className="py-8 text-center text-sm text-muted">No data.</div>}
        </Card>
        <Card title="Top paths" bodyClassName="p-0">
          <table className="nx-table">
            <thead><tr><th>Path</th><th className="w-[35%]">Requests</th><th className="text-right">Avg ms</th></tr></thead>
            <tbody>
              {(d?.topPaths || []).map((x) => (
                <tr key={x.path}>
                  <td className="max-w-[260px] truncate font-mono text-xs">{x.path}</td>
                  <td><div className="flex items-center gap-2"><div className="h-1 flex-1 rounded-full bg-line/70"><div className="h-full rounded-full bg-warm" style={{ width: `${(x.count / maxPath) * 100}%` }} /></div><span className="w-12 text-right font-mono text-xs tabular">{fmtNum(x.count)}</span></div></td>
                  <td className="text-right font-mono text-xs text-muted">{x.avgMs != null ? Math.round(x.avgMs) : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {d && d.topPaths.length === 0 && <div className="py-8 text-center text-sm text-muted">No data.</div>}
        </Card>
      </div>
      {d && d.byStatus.some((s) => s.status.startsWith('5')) && (
        <div className="mt-3 text-xs text-muted"><Badge tone="bad">5xx</Badge> responses present in range — check server logs.</div>
      )}
    </div>
  );
}
