import { useEffect, useMemo, useState } from 'react';
import { AlertTriangle, Plus, ShieldCheck, ShieldX, Trash2 } from 'lucide-react';
import { Badge, Button, IconButton, Input, Modal, Select, Skeleton, toast } from '@/components/ui';
import { fmtDateTime, timeAgo } from '@/lib/format';
import { createIpRule, deleteIpRule, listActivity, listIpRules, type AuditRow, type IpRule } from './api';
import { Card, ErrorNote, PageHeader, RefreshButton, useQuery } from './common';

// ---- IPv4/IPv6 CIDR helpers (for the self-lockout warning; server enforces the real rule) ----
function ipToBig(ip: string): { v: 4 | 6; n: bigint } | null {
  ip = ip.trim().replace(/^::ffff:/i, '');
  if (/^\d+\.\d+\.\d+\.\d+$/.test(ip)) {
    const p = ip.split('.').map(Number);
    if (p.some((x) => x > 255)) return null;
    return { v: 4, n: BigInt(((p[0] << 24) >>> 0) + (p[1] << 16) + (p[2] << 8) + p[3]) };
  }
  if (ip.includes(':')) {
    const [h, t] = ip.split('::');
    const hp = h ? h.split(':') : []; const tp = t !== undefined && t ? t.split(':') : [];
    const fill = t !== undefined ? 8 - hp.length - tp.length : 0;
    const parts = [...hp, ...Array(Math.max(0, fill)).fill('0'), ...tp];
    if (parts.length !== 8) return null;
    let n = 0n; for (const x of parts) n = (n << 16n) + BigInt(parseInt(x || '0', 16));
    return { v: 6, n };
  }
  return null;
}
export function cidrContains(cidr: string, ip: string) {
  const [base, bitsS] = cidr.trim().split('/');
  const a = ipToBig(base), b = ipToBig(ip);
  if (!a || !b || a.v !== b.v) return false;
  const total = a.v === 4 ? 32 : 128;
  const bits = bitsS === undefined ? total : Number(bitsS);
  if (!(bits >= 0 && bits <= total)) return false;
  const shift = BigInt(total - bits);
  return a.n >> shift === b.n >> shift;
}
const validCidr = (c: string) => { const [b, s] = c.trim().split('/'); const a = ipToBig(b); if (!a) return false; if (s === undefined) return true; const n = Number(s); return Number.isInteger(n) && n >= 0 && n <= (a.v === 4 ? 32 : 128); };

function lockoutWarning(rules: IpRule[], ip: string | null) {
  if (!ip) return null;
  const allow = rules.filter((r) => r.kind === 'allow');
  if (rules.some((r) => r.kind === 'block' && cidrContains(r.cidr, ip))) return `Your current IP ${ip} matches a block rule.`;
  if (allow.length && !allow.some((r) => cidrContains(r.cidr, ip))) return `An allowlist is active and your current IP ${ip} is not on it.`;
  return null;
}

export default function Security() {
  const rules = useQuery(listIpRules, []);
  const fails = useQuery(() => listActivity({ action: 'login_failed', limit: 25 }), [], 30_000);
  const [adding, setAdding] = useState(false);
  const r = rules.data?.rules || [];
  const ip = rules.data?.clientIp || null;
  const warn = lockoutWarning(r, ip);
  const remove = async (rule: IpRule) => {
    const next = r.filter((x) => x.id !== rule.id);
    const w = lockoutWarning(next, ip);
    if (w && !confirm(`${w}\n\nAdmins are protected from self-lockout by the server, but double-check. Remove anyway?`)) return;
    try { await deleteIpRule(rule.id); toast.success('Rule removed'); rules.reload(true); } catch (e: any) { toast.error(e.message); }
  };
  return (
    <div>
      <PageHeader title="Security" description="Network access rules, failed sign-ins and the audit trail." actions={<RefreshButton loading={rules.loading} onClick={() => { rules.reload(); fails.reload(); }} />} />
      <Card title="IP rules" actions={<Button size="xs" variant="outline" icon={<Plus size={12} />} onClick={() => setAdding(true)}>Add rule</Button>} bodyClassName="p-0">
        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 border-b border-line/60 px-4 py-2.5 text-xs text-muted">
          <span>Your IP: <span className="font-mono text-ink">{ip || 'unknown'}</span></span>
          <span>If any <Badge tone="ok">allow</Badge> rule exists, only matching IPs can reach the app. <Badge tone="bad">block</Badge> rules always deny.</span>
        </div>
        {warn && <div className="flex items-center gap-2 border-b border-warn/30 bg-warn/[0.07] px-4 py-2.5 text-xs text-warn"><AlertTriangle size={14} />{warn} The server keeps admins from locking themselves out, but other sessions from this IP may be blocked.</div>}
        {rules.error && <div className="p-4"><ErrorNote error={rules.error} /></div>}
        {!rules.data && !rules.error ? <div className="p-4"><Skeleton className="h-16" /></div> : r.length === 0 ? (
          <div className="px-4 py-8 text-center text-sm text-muted">No rules — the app is reachable from any IP (login still required).</div>
        ) : (
          <table className="nx-table">
            <thead><tr><th>Type</th><th>CIDR</th><th>Note</th><th>Added</th><th /></tr></thead>
            <tbody>
              {r.map((x) => (
                <tr key={x.id}>
                  <td>{x.kind === 'allow' ? <Badge tone="ok" icon={<ShieldCheck size={10} />}>allow</Badge> : <Badge tone="bad" icon={<ShieldX size={10} />}>block</Badge>}</td>
                  <td className="font-mono text-xs">{x.cidr}{ip && cidrContains(x.cidr, ip) && <span className="ml-2 text-[10px] text-hot">← you</span>}</td>
                  <td className="text-xs text-muted">{x.note || '—'}</td>
                  <td className="font-mono text-xs text-muted">{x.createdAt ? timeAgo(x.createdAt) : '—'}</td>
                  <td className="text-right"><IconButton size="sm" variant="danger" icon={<Trash2 size={13} />} label="Remove rule" onClick={() => remove(x)} /></td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Card>

