          {fails.error ? <div className="p-4"><ErrorNote error={fails.error} /></div> : !fails.data ? <div className="p-4"><Skeleton className="h-24" /></div> : fails.data.items.length === 0 ? (
            <div className="px-4 py-8 text-center text-sm text-muted">No failed sign-ins. 🛡</div>
          ) : (
            <ul className="max-h-[440px] divide-y divide-line/60 overflow-y-auto">
              {fails.data.items.map((a) => (
                <li key={a.id} className="flex items-center gap-3 px-4 py-2 text-xs">
                  <span className="font-mono text-ink/90">{a.ip || '—'}</span>
                  <span className="flex-1 truncate text-muted">{a.target || a.meta?.email || ''}</span>
                  <span className="font-mono text-muted" title={fmtDateTime(a.ts)}>{timeAgo(a.ts)}</span>
                </li>
              ))}
            </ul>
          )}
        </Card>
        <AuditLog />
      </div>
      <AddRuleModal open={adding} onClose={() => setAdding(false)} rules={r} ip={ip} onSaved={() => rules.reload(true)} />
    </div>
  );
}

function AuditLog() {
  const [action, setAction] = useState('');
  const [items, setItems] = useState<AuditRow[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const load = async (reset: boolean) => {
    setLoading(true);
    try { const r = await listActivity({ action: action || undefined, cursor: reset ? null : cursor }); setItems((x) => (reset ? r.items : [...x, ...r.items])); setCursor(r.nextCursor); setError(null); }
    catch (e: any) { setError(e.message); } finally { setLoading(false); }
  };
  useEffect(() => { load(true); }, [action]); // eslint-disable-line react-hooks/exhaustive-deps
  const actions = useMemo(() => [...new Set(items.map((i) => i.action))].sort(), [items]);
  return (
    <Card title="Audit log" bodyClassName="p-0"
      actions={<Select size="sm" wrapperClassName="w-44" value={action} onChange={setAction} options={[{ value: '', label: 'All actions' }, ...[...new Set([...actions, action].filter(Boolean))].map((a) => ({ value: a, label: a }))]} />}>
      {error && <div className="p-4"><ErrorNote error={error} /></div>}
      <div className="max-h-[440px] overflow-auto">
        <table className="nx-table">
          <thead><tr><th>When</th><th>User</th><th>Action</th><th>Target</th><th>IP</th></tr></thead>
          <tbody>
            {items.map((a) => (
              <tr key={a.id}>
                <td className="whitespace-nowrap font-mono text-xs text-muted" title={fmtDateTime(a.ts)}>{timeAgo(a.ts)}</td>
                <td className="max-w-[180px] truncate text-xs">{a.userEmail || a.userId || '—'}</td>
                <td><Badge tone={/fail|denied|block|delete/.test(a.action) ? 'bad' : /create|grant|allow/.test(a.action) ? 'ok' : 'neutral'} mono>{a.action}</Badge></td>
                <td className="max-w-[240px] truncate font-mono text-xs text-muted" title={a.meta ? JSON.stringify(a.meta) : undefined}>{a.target || '—'}</td>
                <td className="font-mono text-xs text-muted">{a.ip || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
        {!loading && items.length === 0 && !error && <div className="py-8 text-center text-sm text-muted">No audit events.</div>}
      </div>
      {cursor && <div className="border-t border-line/60 p-2 text-center"><Button size="xs" variant="ghost" loading={loading} onClick={() => load(false)}>Load more</Button></div>}
    </Card>
  );
}

function AddRuleModal({ open, onClose, rules, ip, onSaved }: { open: boolean; onClose: () => void; rules: IpRule[]; ip: string | null; onSaved: () => void }) {
  const [cidr, setCidr] = useState('');
  const [kind, setKind] = useState<'allow' | 'block'>('block');
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (open) { setCidr(''); setNote(''); setKind('block'); } }, [open]);
  const valid = validCidr(cidr);
  const warn = valid ? lockoutWarning([...rules, { id: 'new', cidr, kind }], ip) : null;
  const save = async () => {
    setBusy(true);
    try { await createIpRule({ cidr: cidr.trim(), kind, note: note.trim() || undefined }); toast.success('Rule added'); onSaved(); onClose(); }
    catch (e: any) { toast.error(e.message); } finally { setBusy(false); }
  };
  return (
    <Modal open={open} onClose={onClose} title="Add IP rule" size="sm"
      footer={<><Button variant="ghost" onClick={onClose}>Cancel</Button><Button variant={warn ? 'danger' : 'primary'} loading={busy} disabled={!valid} onClick={save}>{warn ? 'Add anyway' : 'Add rule'}</Button></>}>
      <div className="flex flex-col gap-3">
        <Select label="Type" value={kind} onChange={(v) => setKind(v as any)} options={[{ value: 'block', label: 'Block — deny these addresses' }, { value: 'allow', label: 'Allow — only allowlisted IPs may connect' }]} />
        <Input label="IP or CIDR" mono placeholder="203.0.113.0/24" value={cidr} onChange={(e) => setCidr(e.target.value)} error={cidr && !valid ? 'Not a valid IPv4/IPv6 address or CIDR' : undefined}
          hint={ip ? <button type="button" className="text-hot hover:underline" onClick={() => setCidr(ip)}>Use my IP ({ip})</button> : undefined} />
        <Input label="Note" placeholder="Optional" value={note} onChange={(e) => setNote(e.target.value)} />
        {warn && <div className="flex gap-2 rounded-lg border border-warn/30 bg-warn/[0.07] px-3 py-2 text-xs text-warn"><AlertTriangle size={14} className="mt-0.5 shrink-0" /><span><b>Self-lockout risk.</b> {warn}</span></div>}
      </div>
    </Modal>
  );
}
