import { useEffect, useState } from 'react';
import { ArrowDown, ArrowUp, Eye, EyeOff, KeyRound, Plus, Save, X } from 'lucide-react';
import { Badge, Button, IconButton, Input, Select, Skeleton, toast } from '@/components/ui';
import { fmtNum, timeAgo } from '@/lib/format';
import type { ModelInfo } from '@/lib/types';
import { getSettings, saveSettings } from './api';
import { Card, ErrorNote, PageHeader, useQuery } from './common';

export default function SettingsPage() {
  const s = useQuery(getSettings, []);
  const [models, setModels] = useState<ModelInfo[]>([]);
  const [def, setDef] = useState('');
  const [cap, setCap] = useState('');
  const [busy, setBusy] = useState(false);
  const [token, setToken] = useState('');
  const [show, setShow] = useState(false);
  const [tokBusy, setTokBusy] = useState(false);

  useEffect(() => {
    if (!s.data) return;
    setModels(s.data.models.map((m) => ({ ...m })));
    setDef(s.data.defaultModel);
    setCap(s.data.globalDailyTokenCap ? String(s.data.globalDailyTokenCap) : '');
  }, [s.data]);

  const capNum = cap.trim() ? Number(cap.replace(/[_,\s]/g, '')) : null;
  const modelsValid = models.length > 0 && models.every((m) => m.id.trim() && m.label.trim()) && new Set(models.map((m) => m.id.trim())).size === models.length;
  const dirty = !!s.data && (JSON.stringify(models) !== JSON.stringify(s.data.models) || def !== s.data.defaultModel || (capNum ?? null) !== (s.data.globalDailyTokenCap ?? null));

  const save = async () => {
    if (!modelsValid) return toast.error('Each model needs a unique id and a label');
    if (capNum !== null && !(capNum >= 0)) return toast.error('Global cap must be a number');
    setBusy(true);
    try {
      const cleaned = models.map((m) => ({ id: m.id.trim(), label: m.label.trim() }));
      await saveSettings({ models: cleaned, defaultModel: cleaned.some((m) => m.id === def) ? def : cleaned[0].id, globalDailyTokenCap: capNum === null ? null : Math.round(capNum) });
      toast.success('Settings saved'); s.reload(true);
    } catch (e: any) { toast.error('Save failed', { description: e.message }); } finally { setBusy(false); }
  };
  const saveToken = async (clear = false) => {
    setTokBusy(true);
    try {
      await saveSettings({ claudeAuthToken: clear ? '' : token.trim() });
      toast.success(clear ? 'Claude credential cleared' : 'Claude credential updated', { description: clear ? undefined : 'New runs will use it immediately.' });
      setToken(''); setShow(false); s.reload(true);
    } catch (e: any) { toast.error(e.message); } finally { setTokBusy(false); }
  };
  const move = (i: number, d: number) => { const n = [...models]; const [x] = n.splice(i, 1); n.splice(i + d, 0, x); setModels(n); };
  const tokKind = token.trim().startsWith('sk-ant-oat') ? 'OAuth token' : token.trim().startsWith('sk-ant-api') ? 'API key' : token.trim() ? 'unrecognized format' : null;

  if (s.error) return <><PageHeader title="Settings" /><ErrorNote error={s.error} onRetry={() => s.reload()} /></>;
  return (
    <div>
      <PageHeader title="Settings" description="Models, defaults, global caps and the Claude credential."
        actions={<Button variant="primary" size="sm" icon={<Save size={13} />} loading={busy} disabled={!dirty} onClick={save}>Save changes</Button>} />
      {!s.data ? <Skeleton className="h-64" /> : (
        <div className="grid gap-4 xl:grid-cols-2">
          <Card title="Models" actions={<Button size="xs" variant="ghost" icon={<Plus size={12} />} onClick={() => setModels([...models, { id: '', label: '' }])}>Add model</Button>}>
            <p className="mb-3 text-xs text-muted">Shown in every model switcher. <span className="font-mono">id</span> is passed to <span className="font-mono">claude --model</span> (alias like <span className="font-mono">opus</span> or a full model id).</p>
            <div className="flex flex-col gap-2">
              <div className="grid grid-cols-[1fr_1fr_auto] gap-2 px-0.5 text-[10.5px] uppercase tracking-wider text-muted"><span>id</span><span>label</span><span className="w-[92px]" /></div>
              {models.map((m, i) => (
                <div key={i} className="grid grid-cols-[1fr_1fr_auto] items-center gap-2">
                  <Input inputSize="sm" mono value={m.id} placeholder="sonnet" onChange={(e) => setModels(models.map((x, j) => (j === i ? { ...x, id: e.target.value } : x)))} />
                  <Input inputSize="sm" value={m.label} placeholder="Sonnet 5.5" onChange={(e) => setModels(models.map((x, j) => (j === i ? { ...x, label: e.target.value } : x)))} />
                  <div className="flex w-[92px] items-center justify-end">
                    {m.id && m.id === def && <Badge tone="pink" className="mr-1">default</Badge>}
                    <IconButton size="xs" icon={<ArrowUp size={12} />} label="Move up" disabled={i === 0} onClick={() => move(i, -1)} />
                    <IconButton size="xs" icon={<ArrowDown size={12} />} label="Move down" disabled={i === models.length - 1} onClick={() => move(i, 1)} />
                    <IconButton size="xs" variant="danger" icon={<X size={12} />} label="Remove" disabled={models.length <= 1} onClick={() => setModels(models.filter((_, j) => j !== i))} />
                  </div>
                </div>
              ))}
            </div>
          </Card>
          <div className="flex flex-col gap-4">
            <Card title="Defaults & caps">
              <div className="grid gap-3 sm:grid-cols-2">
                <Select label="Default model" value={def} onChange={setDef} options={models.filter((m) => m.id.trim()).map((m) => ({ value: m.id, label: `${m.label || m.id}` }))} />
                <Input label="Global daily token cap" mono placeholder="Unlimited" inputMode="numeric" value={cap} onChange={(e) => setCap(e.target.value)}
                  hint={capNum ? `${fmtNum(capNum)} tokens / day across all users` : 'Empty = no global cap'} error={cap && !(capNum! >= 0) ? 'Must be a number' : undefined} />
              </div>
            </Card>
            <Card title="Claude credential" actions={s.data.claudeAuth.set ? <Badge tone="ok" dot>configured</Badge> : <Badge tone="warn" dot>not set</Badge>}>
              <div className="mb-3 flex items-center gap-3 rounded-lg border border-line bg-bg/50 px-3 py-2.5">
                <KeyRound size={15} className="text-pink" />
                <div className="min-w-0 flex-1">
                  <div className="font-mono text-sm text-ink/90">{s.data.claudeAuth.masked || '••••••••  (none stored — using server env)'}</div>
                  <div className="text-[11px] text-muted">
                    {s.data.claudeAuth.kind ? `${s.data.claudeAuth.kind} · ` : ''}{s.data.claudeAuth.updatedAt ? `updated ${timeAgo(s.data.claudeAuth.updatedAt)}` : 'current value is never shown in full'}
                  </div>
                </div>
              </div>
              <Input
                type={show ? 'text' : 'password'} mono autoComplete="off" spellCheck={false} placeholder="sk-ant-oat01-…  or  sk-ant-api03-…"
                value={token} onChange={(e) => setToken(e.target.value)} label="Replace credential"
                rightSlot={<IconButton size="xs" icon={show ? <EyeOff size={12} /> : <Eye size={12} />} label={show ? 'Hide' : 'Show'} onClick={() => setShow(!show)} />}
                hint={tokKind ? <>Detected: <span className={tokKind === 'unrecognized format' ? 'text-warn' : 'text-ok'}>{tokKind}</span></> : undefined}
              />
              <p className="mt-2.5 text-xs leading-relaxed text-muted">
                Run <code className="rounded bg-panel2 px-1 py-0.5 text-hot">claude setup-token</code> on any machine logged in to the Claude account and paste the token here, or paste an Anthropic API key.
                The value is write-only: it is stored server-side and passed to each run; it is never sent back to the browser.
              </p>
              <div className="mt-3 flex justify-end gap-2">
                {s.data.claudeAuth.set && <Button size="sm" variant="ghost" loading={tokBusy && !token} onClick={() => { if (confirm('Clear the stored credential? Runs will fall back to the server environment value.')) saveToken(true); }}>Clear</Button>}
                <Button size="sm" variant="primary" loading={tokBusy && !!token} disabled={token.trim().length < 20} onClick={() => saveToken()}>Update credential</Button>
              </div>
            </Card>
          </div>
        </div>
      )}
    </div>
  );
}
