import { chromium } from 'playwright';
const base = 'http://127.0.0.1:18080';
const out = process.env.OUT || '../shots';
const pages = (process.argv[2] || 'login,nexus').split(',');
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const p = await ctx.newPage();
const errs = [];
p.on('console', (m) => { if (m.type() === 'error' || m.type()==='warning') errs.push(m.type()+': '+m.text()); });
p.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
for (const name of pages) {
  const [route, action] = name.split(':');
  const url = route === 'login' ? '/login' : route === 'nexus' ? '/' : '/' + route.replace(/_/g, '/');
  await p.goto(base + url, { waitUntil: 'networkidle' });
  await p.waitForTimeout(route === 'login' ? 2600 : 1800);
  if (action === 'hover') { await p.mouse.move(0,0); const pos = await p.evaluate(() => null); }
  if (action === 'palette') { await p.keyboard.press('Control+k'); await p.waitForTimeout(400); }
  if (action === 'new') { await p.keyboard.press('n'); await p.waitForTimeout(400); }
